insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('3c314127-eeef-5bfa-9d07-30522e751c84', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice completes the text with the most logical and precise word or phrase?', '["immense", "unknown", "ordinary", "limited"]'::jsonb, 1, 'The American continents are home to a huge diversity of languages, from Mayo, found in places like Mexico in North America, to Koreguaje, found in places like Colombia in South America. Much like the continents themselves, the variety of native languages in the Americas is _____.'),
  ('9df270bc-a20f-5ff7-8e91-81a5cae395be', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice completes the text with the most logical and precise word or phrase?', '["impractical", "presumptuous", "ambiguous", "customary"]'::jsonb, 2, 'The minor planet 1095 Tulipa was named after the plant genus that includes tulips, but given the sheer number of minor planets that have been discovered (more than 500,000 so far), most are given only an identification number. Because any name given to a minor planet needs to be unique to that body, naming each would be _____.'),
  ('c26022f2-dad6-5586-8269-01800a195459', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice completes the text with the most logical and precise word or phrase?', '["cited in", "apprised of", "unsympathetic to", "placated by"]'::jsonb, 3, 'Drivers who strongly believe that the toll they must pay to use the San Luis Pass-Vacek Toll Bridge, which spans the San Luis Pass in Texas, is currently too high are likely to be ____ arguments for increasing the toll. Advocates for a higher toll are likely to have more success if they instead direct their arguments toward a more persuadable segment of the population.'),
  ('184e96d0-f1ec-5426-aa4e-fdd57bd310d3', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice completes the text with the most logical and precise word or phrase?', '["bestowed on", "wrought by", "allocated to", "concealed from"]'::jsonb, 4, 'Though few critics consider Vasily Grossman’s novel Stalingrad—which focuses on the experience of the Soviet Union in the early years of World War II—to be as well written as his later book Everything Flows, some compliment it despite the damage _____ Soviet censors: Gary Saul Morson in The New York Review of Books called the novel "remarkably bold."'),
  ('178fa45e-3d60-5800-af7c-cc4b7eb23a8d', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice best describes the overall structure of the text?', '["It discusses several recent innovations in product manufacturing and then suggests some potential applications of those innovations.", "It describes a company’s recent success with new products and then explains multiple factors that may have contributed to that success.", "It presents two contrasting product-marketing techniques and then provides examples of one of those techniques.", "It introduces a trend in consumer products and then explains how the trend both benefits and poses a challenge to companies."]'::jsonb, 5, 'Companies are providing consumers with more opportunities to purchase customized products than ever before. Whether buying customized sneakers, jewelry, or clothing, consumers can participate in the design of products to meet their specific needs and tastes. In turn, companies profit too: studies have shown that consumers are willing to pay more and wait longer for a customized product. Still, it can be difficult for companies to offer customization while keeping costs low, as the standard methods of mass production may not be able to accommodate making a unique product each time.'),
  ('d30a4fe5-ffd4-5958-a074-02db4a591c36', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice best describes the main purpose of the text?', '["To explain why historians of capitalism and Africanist scholars disagree about which activities are features of capitalism", "To present and account for a potentially misleading characteristic of the work of historians of capitalism", "To describe and evaluate a method used by Africanist scholars that distinguishes their work from that of historians of capitalism", "To summarize a debate between historians of capitalism and Africanist scholars about how to interpret longitudinal economic data from archival records"]'::jsonb, 6, 'Karl Polanyi and other historians rarely discuss domestic capitalism in Africa before the period of European colonization, implicitly presenting capitalism as external to and imposed on Africa. Mariana Candido and other Africanist scholars have shown, however, that in parts of Africa, centrally administered industrial production, the legal treatment of land as private property, and other features of capitalism predated colonization. One reason for this discrepancy is that historians of capitalism tend to focus on longitudinal economic data drawn from archival records, which do not exist for much of precolonial Africa.'),
  ('756381ea-88e8-5895-aa37-dfe9696b0051', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice best states the main purpose of the text?', '["To offer commentary on a human foible that may account for why the people of Milby view the Countess Czerlaski as they do", "To speculate on the circumstances under which the unfavorable opinion of the Countess Czerlaski that is held by the people of Milby could be improved", "To explain why the people of Milby are somewhat correct to reproach the Countess Czerlaski for her misdeeds", "To engage the reader’s compassion for both the Countess Czerlaski and the people of Milby by detailing their different viewpoints"]'::jsonb, 7, 'The following text is adapted from George Eliot’s 1857 short story "The Sad Fortunes of the Rev. Amos Barton." The Countess Czerlaski is a newcomer to the town of Milby.
I am by no means sure that if the good people of Milby had known the truth about the Countess Czerlaski, they would not have been considerably disappointed to find that it was very far from being as bad as they imagined. Nice distinctions are troublesome. It is so much easier to make up your mind that your neighbour is good for nothing, than to enter into all the circumstances that would oblige you to modify that opinion.'),
  ('db825951-27b6-5daf-beff-85caa18a311b', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Based on the text, what most likely motivates Tía Ana’s behavior during Salomé’s salon?', '["She is frustrated because she needs assistance elsewhere in the house, but Salomé is unavailable while entertaining the guests.", "She is anxious for the gathering to disperse so that she can ready the space for her own needs.", "She is impatient to share her plans to start a new school with the guests and hopes they will support her.", "She finds the guests to be dull and is eager to find a way to leave the salon."]'::jsonb, 8, 'The following text is from Julia Alvarez’s 2000 novel In the Name of Salomé. Salomé, a poet, is hosting guests in the front parlor of her family home, and Ramona is her sister. A salon is a social gathering for the exploration of intellectual ideas.
It was evening when the two men got up to leave. Tía Ana had already come into the room several times to see if these guests had departed yet. The front parlor had always been her special province, as she used it for her little school. Now, every evening, it turned into Salomé’s salon, as Ramona called it, and it was never in order for its transformation back to a classroom the following morning.

©2000 by Julia Alvarez'),
  ('1c0363c9-a9cc-5440-822c-30b10024ec5d', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'What claim does the text make about the demand for petroleum?', '["Companies involved in petroleum extraction are not affected by the demand for petroleum.", "The societal preference for low-carbon energy sources is a factor in the demand for petroleum.", "The demand for petroleum follows a predictable annual cycle.", "Companies involved in petroleum extraction can benefit from a decline in the demand for petroleum."]'::jsonb, 9, 'Companies involved in petroleum extraction include drilling equipment among their assets. But petroleum extraction is a very carbon-intensive industry, so as social attitudes increasingly favor using less carbon intensive sources of energy demand for petroleum falls and the drilling equipment will eventually, or even suddenly, become a liability as reduced petroleum prices make it more difficult to recover the expense of maintaining such equipment.'),
  ('a43083b8-14fe-5ea9-9e24-b1c26771b4d7', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'According to the text, which trait do researchers think may contribute to a flat-headed cat’s ability to purr?', '["The shape of the flat-headed cat’s larynx", "The ligament attaching the hyoid bone to the flat-headed cat’s skull", "The flat-headed cat’s rigid hyoid bone", "The relative size of the flat-headed cat’s body and throat"]'::jsonb, 10, 'Why do flat-headed cats purr but jaguars roar? Researchers hypothesize that this difference between the two feline species may be partly due to a U-shaped bone in their throats called the hyoid. Flat-headed cats, which are much smaller than jaguars, have a rigid hyoid that rumbles when the cat’s larynx vibrates, resulting in a purr. By contrast, jaguars have a somewhat flexible hyoid, and the bone is attached to the skull with a stretchy ligament that flat-headed cats lack. These traits allow jaguars and most other species of big cats to produce powerful roars. The same traits may also prevent most big cats from purring.'),
  ('d8bd23ee-9228-5e88-8602-517868a1ca22', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice most effectively uses data from the table to complete the example?', '["37.26 square miles.", "3.61 square miles.", "23.57 square miles.", "15.99 square miles."]'::jsonb, 11, '**Total Areas of Five Hawaiian Home Lands**

| Home land | Area (square miles) |
| Nanakuli | 3.61 |
| Kawaihae | 15.99 |
| Kamoku-Kapulena | 7.47 |
| Kahikinui | 37.26 |
| Waimea | 23.57 |

Hawaiian home lands are areas of public land in the state of Hawaii that have been reserved for use by the Kanaka Maoli, or the Native Hawaiian people. The largest of the home lands, Humuula-Upper Piihonua, covers nearly 100 square miles on the island of Hawai''i. Most of the home lands are much smaller. For example, the total area of Kamoku-Kapulena is 7.47 square miles, and the total area of Nanakuli is ______'),
  ('cf0baf4f-9ad6-5f16-8c04-bce5d2e6eba7', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice most effectively uses data from the table to complete the example?', '["distance between Mexico City and Monterrey with the distance between Jakarta and Singapore.", "number of passengers who traveled between Mumbai and Delhi in 2017 with the number who traveled between Hong Kong and Manila during that same year.", "number of passengers who traveled between Jakarta and Singapore in 2017 with the number who traveled that same route in 2018.", "number of passengers who traveled between Jakarta and Singapore in 2018 with the number who traveled between Mexico City and Monterrey during that same year."]'::jsonb, 12, '**Highly Traveled Commercial Airline Routes in 2017-18**

| Location 1 | Location 2 | Distance of route (kilometers) | 2018 passengers | 2017 passengers | Domestic or international |
| Hong Kong | Manila | 1,145 | 3,008,842 | 2,907,228 | international |
| Jakarta | Singapore | 896 | 4,812,342 | 4,810,602 | international |
| Mumbai | Delhi | 1,150 | 7,392,155 | 7,129,943 | domestic |
| Mexico City | Monterrey | 729 | 3,474,971 | 3,202,091 | domestic |

A study of commercial airline routes that carried the greatest number of passengers in 2017 and 2018 shows that, in general, domestic routes (routes within a single country) carried many more passengers than international routes. However, a few international routes were so popular that they carried more travelers than some of the most highly traveled domestic routes, as can be seen when comparing the _____'),
  ('22ed6470-49ca-5ea1-854b-eb9498e8289c', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which finding, if true, would most directly support the second research team’s hypothesis?', '["A study using obstructions that created large vortices in low-visibility conditions found that the devil catfish (Bagarius bagarius), which has a relatively wide head, bumped into more than half of the obstructions.", "A study using obstructions that created large vortices in low-visibility conditions found that the intermediate-headed dusky smooth-hound (Mustelus canis) bumped into the obstructions just as often as the wide-headed Synodontis macropunctata did.", "A study using obstructions that created large vortices in low-visibility conditions found that the wide-headed Synodontis macropunctata bumped into obstructions more often than the intermediate-headed dusky smooth-hound (Mustelus canis) did.", "A study using obstructions that created large vortices in low-visibility conditions found that some specimens of the intermediate-headed rainbow trout (Oncorhynchus mykiss) bumped into the obstructions more often than other specimens of the same fish did."]'::jsonb, 13, 'Water flowing around an obstruction creates vortices (swirls) that vary in size with the obstruction’s size and position, and fish sense these vortices in order to navigate around the obstructions. Using models of three fish head shapes—narrow (low ratio of width to length), intermediate, and wide (high ratio of width to length)—Yuzo R. Yanagisuru, Otar AkanyetI, and James C. Liao showed that as vortex size increases, pressure fluctuations at the snout increase for narrow-headed and intermediate-headed fish but remain low for wide-headed fish. A second research team has therefore hypothesized that in low visibility, a fish will be more likely to avoid an obstruction when the associated pressure fluctuations at the fish’s snout are greater.'),
  ('28c95c1d-fa8a-5f42-bac3-50781bd4031c', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice most effectively uses data from the table to complete the example?', '["Zambia, which has a low density, with Benin, which has a similar density despite both countries having different geographic sizes.", "the geographic size of Mali (1,240,000 square kilometers) with its relatively high population of 17,600,000 inhabitants.", "Mali, which has a high population of 17,600,000 inhabitants and a relatively low density of 14.2 inhabitants/square kilometer, with Lesotho, which has a much lower population and a higher density.", "the populations of both Lesotho and Benin in 2015 with their populations in 2010."]'::jsonb, 14, '**Population and Population Density of African Countries in 2015**

| Country | 2 Density (inhabitants/km) | 2 Area (km) | Estimated population |
| Lesotho | 70.3 | 30,355 | 2,135,000 |
| Mali | 14.2 | 1,240,000 | 17,600,000 |
| Zambia | 21.5 | 752,614 | 16,212,000 |
| Benin | 96.6 | 112,620 | 10,880,000 |

As the second most populous continent in the world, Africa was home to an estimated 1.186 billion people in 2015. In a paper for a social studies class, a student nonetheless notes that countries with very large populations may be less densely populated than are countries with much smaller populations, as can be seen by comparing _____'),
  ('8216b9dc-ca73-52ea-9000-fb515c2faf49', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice most logically completes the text?', '["the apparent difference between the two studies'' results may be partly attributable to the 1976 study using a different standard to determine handedness than the 1999 study did.", "the right-handedness exhibited by the captive chimpanzees and catarrhine monkeys might be, in part, an effect of extended contact with humans.", "the number of individuals in the study of captive chimpanzees and catarrhine monkeys is likely too small to support the claim that the species tends toward right handedness.", "the number of individuals in the study of wild chimpanzees is probably too small to support the claim that no tendency toward right-handedness was found in that population."]'::jsonb, 15, 'Humans have a very strong bias toward right handedness, with approximately 85-90% having right as their dominant hand. Among studies of nonhuman primates, James Welles’s 1976 study of captive chimpanzees and catarrhine monkeys reported more right-handed individuals than left-handed ones, but William C. McGrew and colleagues'' 1999 study of wild chimpanzees did not find a tendency toward right-handedness. It’s important to note, however, that captive animals spend significantly more time with humans than wild animals do, and therefore _____'),
  ('5dbfa78e-3b15-5db5-ba9e-a1c8968fc76a', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["cosmetic chemists'',", "cosmetic chemist''s,", "cosmetic chemists,", "cosmetic’s chemists,"]'::jsonb, 16, 'Used in everything from food to cleaning products, emulsifiers are compounds that serve to stabilize an emulsion—a mixture of two or more liquids that otherwise would not easily blend together. The emulsifiers used by _____ like palmitic acid, allow these scientists to blend oil and water into homogeneous formulations such as lotions and perfumes.'),
  ('79e232c1-26f9-5cbd-a231-085e64bb4c5d', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["century,", "century", "century, but", "century that"]'::jsonb, 17, 'Many mechanical calculators were powered by a notched cylinder mechanism called the Leibniz wheel. Leibniz wheel calculators were popular in the first half of the twentieth _____ these ingenious devices were eventually replaced by electronic calculators.'),
  ('7ea729ab-c249-56ee-9865-16feb370a139', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Smith—", "Smith:", "Smith,", "Smith"]'::jsonb, 18, 'Nigerian American artist Toyin Ojih Odutola uses black-ink pens to create highly detailed drawings of human figures. Her portrait of novelist Zadie _____ is displayed in the National Portrait Gallery in London.'),
  ('4512ea9b-2174-52d1-af9d-60e62ba79b8f', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["drummer, Dennis Chambers", "drummer Dennis Chambers,", "drummer Dennis Chambers", "drummer, Dennis Chambers,"]'::jsonb, 19, 'Though he would go on to work with many respected musicians, including Paul Hanson on his album Frolic in the Land of Plenty, American _____ may be best known for his time with Sugar Hill Records, where he helped craft the sound of early hip hop music.'),
  ('4f2067d6-e2b7-56bf-b7f9-be7dc3be0ada', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["surface, however;", "surface, however,", "surface; however,", "surface. However,"]'::jsonb, 20, 'Between June 22 and July 2 each year, particles shed by comet 7P/Pons-Winnecke enter Earth’s atmosphere at a velocity of 18 kilometers per second. Relatively few of these particles are likely to reach Earth’s _____ since the meteoroids'' compression of the air surrounding them causes the vast majority to burn up in the mesosphere, producing the June Boötid meteor shower.'),
  ('a32e66b0-9da6-534a-98c5-93dfb45393a1', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice completes the text with the most logical transition?', '["At that time,", "For example,", "In other words,", "However,"]'::jsonb, 21, 'While most animals prefer the safety of nighttime migration, many poisonous amphibians—a category that includes the red-bellied newt and the fire salamander—safely engage in migratory behavior during the day. _____ with the sun in the sky, the amphibians'' striking color patterns deter visually oriented daytime predators by serving as a warning of toxicity.'),
  ('866f3c2d-52e0-544a-931d-f4569b988e74', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice completes the text with the most logical transition?', '["For this reason,", "However,", "For example,", "Alternatively,"]'::jsonb, 22, 'Residents of Cairo, Egypt, rely on its rapid transit system, the Cairo Metro, for millions of trips each year. _____ city officials strive to maintain the system’s 71 stations to ensure each of these journeys is as smooth as possible.'),
  ('9c7b689e-b8ee-5ff5-9e51-7d0ef8e38927', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice completes the text with the most logical transition?', '["consequently,", "similarly,", "in sum,", "however,"]'::jsonb, 23, 'Box modeling, used by digital artists to develop 3D assets for video games, yields objects with precise mathematical proportions. Granted, as they are formed from perfect geometric shapes, such 3D elements lack organic realism; _____ post-modeling processes such as UV surface mapping are needed to achieve the level of verisimilitude gamers expect.'),
  ('58a32418-1dd0-5252-88a7-b611d867c8a8', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'The student wants to emphasize a difference between the two lighthouse keepers. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["As the lighthouse keeper at Point Fermin Light, Thelma Austin helped watercraft navigate at night.", "From 1862 to 1880, the nighttime waters of Maine were made more navigable thanks to Betsy Morrow Humphrey.", "Betsy Morrow Humphrey worked as a lighthouse keeper in an earlier century than did Thelma Austin.", "Betsy Morrow Humphrey and Thelma Austin both played crucial roles in ensuring safe navigation for watercraft in past centuries."]'::jsonb, 24, 'While researching a topic, a student has taken the following notes:

Lighthouses send out crucial light signals to help ships and other watercraft navigate at night. Before automation, lighthouses were run by lighthouse keepers.
Betsy Morrow Humphrey was the lighthouse keeper at Monhegan Island Light in Maine. She held this position from 1862 to 1880.
Thelma Austin was the lighthouse keeper at Point Fermin Light in California.
She held this position from 1925 to 1941.'),
  ('8ed636be-492c-520d-ae65-f0d218389ca4', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'The student wants to recount the sequence of events proposed by the researchers. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["According to researchers'' simulations, debris from Saturn’s rings would likely have caused Chrysalis—a large moon orbiting Saturn—to break apart around 160 million years ago.", "In a 2022 study, researchers proposed that Saturn was once orbited by a large moon that broke apart.", "Around 160 million years ago, a large moon (Chrysalis) may have come close enough to Saturn that tidal forces broke the moon apart; its debris then formed the planet’s rings.", "If a moon orbiting a planet (like Saturn) comes close enough to that planet, tidal forces can cause the moon to break apart."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

If a moon orbiting a planet comes close enough to that planet, tidal forces can cause the moon to break apart.
In a 2022 study, researchers proposed that Saturn was once orbited by a large moon they named Chrysalis.
Their simulations indicated that Chrysalis would likely have come very close to Saturn around 160 million years ago.
At that distance, Chrysalis would have been broken apart by tidal forces.
The researchers hypothesized that the resulting debris formed Saturn’s rings.'),
  ('1b49b2da-5f60-5ecb-9f4a-5639b47f2888', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'Which choice most effectively uses information from the given sentences to emphasize a similarity between the two birds?', '["While each exhibits unique traits of its own, the brown violetear and the little hermit both have black bills.", "The little hermit is a small hummingbird identifiable by its white central tail feathers and its long, black, curved bill.", "Though they share several traits in common, the brown violetear is larger than the little hermit.", "Birds of Northern South America is an expertly compiled guidebook by ornithologists Robin Restall, Clemencia Rodner, and Miguel Lentino."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Birds of Northern South America is an identification guidebook by ornithologists Robin Restall, Clemencia Rodner, and Miguel Lentino.
It lists the thirty-five hummingbird species found in Suriname.
The brown violetear is a large hummingbird found in Suriname.
It is identifiable by its dark violet ear patches and its short, black, straight bill.
The little hermit is a small hummingbird found in Suriname.
It is identifiable by its white central tail feathers and its long, black, curved bill.'),
  ('d5c084b6-57ce-5873-8935-ad420b69674a', 'cd58ae50-c46e-5c5c-bcdd-48b08a3de7cf', 'The student wants to emphasize the effect media had on building Wong Fei-hung’s legacy. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Thanks to his depiction in over a hundred pieces of media, Wong Fei-hung was locally known as a successful physician and Hung Ga Kung Fu master.", "Wong Fei-hung’s abilities as a kung fu master are depicted in many media, including the 1991 film Once Upon a Time in China.", "Various media have depicted Wong Fei-hung, the successful physician and kung fu master who became an internationally known folk hero.", "Though he was known locally during his lifetime, Wong Fei-hung’s later depiction in television, film, and other media has turned him into an internationally known folk hero."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Little is known about the life of Wong Fei-hung (1847-1925).
He was born near Foshan, China, and gained local recognition as a physician and Hung Ga (also known as Hung Gar) Kung Fu master.
He achieved many incredible martial arts feats—some confirmed and some rumored. He has become an internationally known folk hero thanks to his depiction in over a hundred films, television shows, and other media.
In the 1991 film Once Upon a Time in China, actor Jet Li portrays Wong Fei-hung using superhuman kung fu abilities to save his community.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('3c314127-eeef-5bfa-9d07-30522e751c84', 0, null, '**Choice A is correct.** The passage describes "a huge diversity of languages," so the variety being described is large; "immense" is the synonym that best matches that idea and completes the comparison to the continents themselves.
**Choice B is incorrect.** "Unknown" does not follow from the passage, which explicitly states there is a "huge diversity," so the variety is not characterized as unknown.
**Choice C is incorrect.** "Ordinary" implies common or unremarkable, which contradicts the passage’s description of a "huge diversity."
**Choice D is incorrect.** "Limited" is the opposite of what the passage states; the text emphasizes a large, not limited, variety of native languages.
**Faster approach:** Look for a direct synonym in the answer choices that matches the passage’s key descriptor (here, "huge diversity" → "immense").'),
  ('9df270bc-a20f-5ff7-8e91-81a5cae395be', 0, null, '**Choice A is correct.** The sentence emphasizes the very large number of minor planets discovered (more than 500,000), and it concludes that giving each a unique name would be not feasible; "impractical" precisely captures that idea of something not reasonable or workable given the scale. The surrounding phrasing —"sheer number" and the requirement that names be unique — supports a meaning related to feasibility rather than attitude or clarity.
**Choice B is incorrect.** "Presumptuous" means overstepping due to arrogance; nothing in the sentence suggests naming would be arrogant or inappropriate in that sense.
**Choice C is incorrect.** "Ambiguous" means unclear or having multiple meanings, but the issue described is quantity and uniqueness, not lack of clarity.
**Choice D is incorrect.** "Customary" means usual or traditional; the sentence argues naming each would be problematic, not that it would be the norm.
**Faster approach:** Note the cue "sheer number" and the uniqueness requirement; immediately map that to a word about feasibility ("impractical") rather than attitude or clarity.'),
  ('c26022f2-dad6-5586-8269-01800a195459', 2, null, '**Choice C is correct.** The sentence contrasts drivers who already think the toll is too high with the people toward whom advocates should direct arguments. If drivers believe the toll is too high, they will not be receptive to proposals to raise it; they will be "unsympathetic to" arguments for increasing the toll, which makes the sentence logical and grammatically coherent.
**Choice A is incorrect.** "Cited in" is ungrammatical here: drivers cannot be "cited in arguments" in the intended sense, and it doesn’t express receptiveness or opposition.
**Choice B is incorrect.** "Apprised of" means informed about the arguments, which doesn’t capture the intended lack of support or receptiveness.
**Choice D is incorrect.** "Placated by" means soothed or pacified by the arguments; that is the opposite of what the context requires, since these drivers already find the toll too high.
**Faster approach:** Focus on the logical relationship implied by the contrast words (advocates should direct their arguments toward a more persuadable group) and pick the choice that denotes lack of receptiveness; eliminate options that are neutral or opposite in meaning.'),
  ('184e96d0-f1ec-5426-aa4e-fdd57bd310d3', 1, null, '**Choice B is correct.** The phrase "damage wrought by Soviet censors" precisely means harm caused by the censors; "wrought by" is an idiomatic and formal way to indicate that the censors produced or inflicted the damage, which fits the sentence context about critics qualifying their praise despite censorship.
**Choice A is incorrect.** "Bestowed on" means "given to" in a positive sense and does not collocate naturally with "damage," so it contradicts the intended meaning.
**Choice C is incorrect.** "Allocated to" means "assigned" or "distributed to" and does not convey causation or harm, so it is not logical here.
**Choice D is incorrect.** "Concealed from" means "hidden from"; that phrase would imply the damage was hidden from the censors, which conflicts with the sentence’s meaning that the censors caused the damage.
**Faster approach:** Look for a verb phrase that shows causation of "damage"; eliminate choices that imply giving, assigning, or hiding rather than causing.'),
  ('178fa45e-3d60-5800-af7c-cc4b7eb23a8d', 3, null, '**Choice D is correct.** The passage opens by describing a trend—greater opportunities for consumers to purchase customized products—and then explains both a benefit (consumers will pay more and wait longer, so companies profit) and a challenge (difficulty keeping costs low because mass-production methods may not handle unique items). This matches the introduced trend followed by both positive and negative effects.
**Choice A is incorrect.** The passage does not discuss several innovations or potential applications; it focuses specifically on customization as a trend and its implications, not on multiple technologies or applications.
**Choice B is incorrect.** The passage is not a company success story and does not list factors contributing to particular success; it discusses a general market trend.
**Choice C is incorrect.** The passage does not present two contrasting marketing techniques; it contrasts benefits and challenges of a single technique (customization), not two techniques.
**Faster approach:** Identify the topic sentence (trend) and then note whether following sentences describe advantages, disadvantages, or examples—match that pattern to the answer choice.'),
  ('d30a4fe5-ffd4-5958-a074-02db4a591c36', 1, null, '**Choice B is correct.** The passage highlights a characteristic of historians of capitalism—their reliance on longitudinal archival economic data—and explains how that characteristic can mislead by making capitalism appear external to Africa. The author both presents the characteristic (focus on archival records) and accounts for its effect (such records are scarce for precolonial Africa, producing a misleading impression).
**Choice A is incorrect.** The passage does not primarily seek to explain why scholars disagree about what counts as capitalist activity; rather it explains how a methodological habit leads to a misleading portrayal of capitalism’s presence in Africa.
**Choice C is incorrect.** The passage does not describe or evaluate a specific method used by Africanist scholars; it only cites their findings that some capitalist features predated colonization.
**Choice D is incorrect.** The passage does not summarize a debate about interpreting archival longitudinal data; it points out that reliance on such data by historians produces an incomplete view, not a detailed debate about interpretation.
**Faster approach:** Identify the author’s main claim (what explanation or problem is offered) and then pick the choice that says the same thing in more general terms—here, a misleading methodological characteristic of historians'' work.'),
  ('756381ea-88e8-5895-aa37-dfe9696b0051', 0, null, '**Choice A is correct.** The passage criticizes a common human tendency—quickly judging neighbors without considering nuance—by noting that townspeople imagine the Countess to be worse than she is and that “nice distinctions are troublesome.” This is an explicit commentary on the foible that explains why Milby views the Countess as it does.
**Choice B is incorrect.** The passage does not speculate about specific circumstances that would change the town’s view; it simply notes that circumstances exist which would modify opinion, not which ones or how they would do so.
**Choice C is incorrect.** The author does not defend reproach or argue that the townspeople are justified; instead the tone suggests their judgment is lazy and likely unfair.
**Choice D is incorrect.** The passage does not seek to evoke compassion for both parties or present both viewpoints in sympathetic detail; it focuses on criticizing the townspeople’s quick judgments.
**Faster approach:** For main-purpose questions, restate the author’s central claim in one sentence; the choice that matches that restatement is the answer.'),
  ('db825951-27b6-5daf-beff-85caa18a311b', 1, null, '**Choice B is correct.** The passage states that the front parlor "had always been her special province, as she used it for her little school," and that in the evenings it "turned into Salomé’s salon, as Ramona called it, and it was never in order for its transformation back to a classroom the following morning." Tía Ana repeatedly coming into the room to see if the guests had left indicates she wants the gathering to end so she can prepare the room again for her school.
**Choice A is incorrect.** Nowhere does the passage mention Tía Ana needing assistance elsewhere in the house or being frustrated for that reason; her repeated checks focus on the room’s availability.
**Choice C is incorrect.** The text gives no evidence that Tía Ana intends to propose a new school to the guests or seeks their support; her concern is about the room’s use.
**Choice D is incorrect.** The passage does not suggest she finds the guests dull or wants to leave the salon herself; rather, she is concerned about restoring the room for her school.
**Faster approach:** Identify the character’s repeated action (checking the room) and connect it to the stated reason for the room’s importance (her classroom). That direct cause–effect linkage quickly eliminates choices that introduce unsupported motives.'),
  ('1c0363c9-a9cc-5440-822c-30b10024ec5d', 1, null, '**Choice B is correct.** The passage states that "as social attitudes increasingly favor using less carbon intensive sources of energy demand for petroleum falls," explicitly linking societal preference for lower-carbon energy to reduced demand for petroleum. This directly supports the claim that societal preference is a factor affecting petroleum demand.
**Choice A is incorrect.** The passage describes how changing social attitudes reduce demand, so companies are affected by demand changes; the choice contradicts the passage.
**Choice C is incorrect.** The passage says nothing about a predictable annual cycle; it discusses a decline tied to social attitudes, not cyclical timing.
**Choice D is incorrect.** The passage argues the opposite: a decline in demand makes drilling equipment a liability, harming companies rather than benefiting them.
**Faster approach:** Locate the clause that links cause and effect (here, "as... favor... demand for petroleum falls") and match that explicit relationship to the answer choices to eliminate distractors quickly.'),
  ('a43083b8-14fe-5ea9-9e24-b1c26771b4d7', 2, null, '**Choice C is correct.** The passage states that flat-headed cats “have a rigid hyoid that rumbles when the cat’s larynx vibrates, resulting in a purr,” directly linking a rigid hyoid bone to the ability to purr.
**Choice A is incorrect.** The passage mentions the larynx vibrating, but it does not say the shape of the larynx causes purring; it identifies the rigid hyoid as the contributing trait.
**Choice B is incorrect.** The passage says jaguars have a stretchy ligament attaching the hyoid to the skull; flat-headed cats lack that stretchy ligament, so the ligament is not cited as enabling their purr.
**Choice D is incorrect.** Although the passage notes flat-headed cats are much smaller than jaguars, it does not attribute purring to their relative size; it points to the rigid hyoid as the relevant trait.
**Faster approach:** Scan the sentence that contrasts flat-headed cats and jaguars for the specific anatomical feature; the explicit phrase “rigid hyoid” identifies the correct choice every time.'),
  ('d8bd23ee-9228-5e88-8602-517868a1ca22', 1, null, '**Choice B is correct.** The passage asks for the total area of Nanakuli, and the table lists Nanakuli with an area of $3.61$ square miles, so $3.61$ square miles completes the sentence accurately.
**Choice A is incorrect.** $37.26$ square miles is the area listed for Kahikinui, not Nanakuli, so it does not match the requested home land.
**Choice C is incorrect.** $23.57$ square miles is the area for Waimea in the table, not Nanakuli, so it is not the correct value to fill the blank.
**Choice D is incorrect.** $15.99$ square miles corresponds to Kawaihae in the table; it is not the area given for Nanakuli and therefore is not correct.
**Faster approach:** Scan the table for the row labeled Nanakuli and use the adjacent area value; for table-based questions, matching the row label to its corresponding cell is the quickest reliable method.'),
  ('cf0baf4f-9ad6-5f16-8c04-bce5d2e6eba7', 3, null, '**Choice D is correct.** The passage claims that some international routes carried more travelers than some highly traveled domestic routes; comparing the 2018 passenger counts for an international route and a domestic route demonstrates this. The table shows Jakarta–Singapore (international) had 4,812,342 passengers in 2018, while Mexico City–Monterrey (domestic) had 3,474,971 in 2018, so the international route carried more travelers than that domestic route.
**Choice A is incorrect.** The passage’s point concerns passenger counts, not distances; comparing distances does not support the claim about passenger numbers.
**Choice B is incorrect.** Both choices in B compare 2017 passenger counts but between two routes where Mumbai–Delhi (domestic) had 7,129,943 in 2017 and Hong Kong–Manila (international) had 2,907,228 in 2017, which would contradict the passage’s example rather than illustrate it.
**Choice C is incorrect.** Comparing 2017 and 2018 passenger counts for the same international route only shows change over time for that route; it does not compare an international route to a domestic route as required.
**Faster approach:** To show that an international route exceeded a domestic one, directly compare the passenger counts for an international route and a domestic route for the same year using the table’s numbers (pick 2018 or 2017 consistently).'),
  ('22ed6470-49ca-5ea1-854b-eb9498e8289c', 2, null, '**Choice C is correct.** The hypothesis predicts that greater pressure fluctuations at the snout lead to more avoidance (fewer collisions). From the first study, intermediate-headed fish experience increased snout pressure fluctuations with larger vortices, while wide-headed fish do not. Therefore, finding that the wide-headed Synodontis macropunctata bumped into obstructions more often than the intermediate-headed dusky smooth-hound is direct evidence that lower snout pressure fluctuations (wide head) correspond to poorer avoidance, supporting the hypothesis.
**Choice A is incorrect.** It reports only that a wide-headed species bumped into many obstructions, but gives no comparison with narrower-headed species; it does not show that bumping correlates with relative snout pressure fluctuations.
**Choice B is incorrect.** If intermediate-headed fish bumped just as often as wide-headed fish, that would contradict the hypothesis (which predicts better avoidance by intermediate-headed fish) rather than support it.
**Choice D is incorrect.** Variation among specimens of the same intermediate-headed species does not link bumping rates to differences in snout pressure fluctuations between head-shape types, so it does not directly support the hypothesis.
**Faster approach:** Identify which head shapes should produce higher snout pressure fluctuations (narrow/intermediate) and then look for the result that those shapes have fewer collisions than wide-headed fish; the choice showing that wide-headed fish collide more directly supports the hypothesis.'),
  ('28c95c1d-fa8a-5f42-bac3-50781bd4031c', 2, null, '**Choice C is correct.** The table shows Mali has a population of 17,600,000 and a density of 14.2
$2$
inhabitants/km, while Lesotho has a much smaller population (2,135,000) but a much higher density (70.3
$2$
inhabitants/km). This directly illustrates that a larger population does not necessarily imply a higher population density, which is the point the student wants to make.
**Choice A is incorrect.** The choice claims Zambia and Benin have similar densities, but the table lists Zambia
$2$
at 21.5 and Benin at 96.6 inhabitants/km, which are not similar.
**Choice B is incorrect.** That statement only cites Mali’s size and population and does not compare a large population with a smaller one that has higher density.
**Choice D is incorrect.** The table gives 2015 populations only; it does not provide 2010 figures, so this comparison is unsupported.
**Faster approach:** Scan the table for one country with high population but low density and one with low population but high density (compare the numbers directly); that pair will illustrate the point.'),
  ('8216b9dc-ca73-52ea-9000-fb515c2faf49', 1, null, '**Choice B is correct.** The passage contrasts results from captive versus wild primates and immediately notes that captive animals spend more time with humans; the most logical completion is that the observed right-handedness in captive animals could result from their extended contact with humans, providing a direct causal explanation for the difference between the studies.
**Choice A is incorrect.** The sentence fragment given links time spent with humans to a likely effect, not to differences in measurement standards; nothing in the passage suggests different handedness standards were used.
**Choice C is incorrect.** The passage does not mention sample sizes for the 1976 study, so asserting that the number of individuals is too small is unsupported and unrelated to the point about human contact.
**Choice D is incorrect.** Similarly, the passage offers no information about sample sizes in the wild study; the immediate context points to human interaction as an explanatory factor, not inadequate sample size.
**Faster approach:** For inference completions, focus on the clause just introduced (here, more human contact) and choose the option that gives a direct, plausible consequence of that clause; eliminate choices that introduce unsupported new issues (like sample size or methodology).'),
  ('5dbfa78e-3b15-5db5-ba9e-a1c8968fc76a', 2, null, '**Choice C is correct.** The verb phrase "used by" requires a noun or noun phrase as its object, so the simple plural noun "cosmetic chemists" fits. The sentence then reads: "The emulsifiers used by cosmetic chemists like palmitic acid allow these scientists to blend...," which correctly supplies the people who use the emulsifiers (cosmetic chemists).
**Choice A is incorrect.** "cosmetic chemists''" is the plural possessive; that would indicate something belonging to the chemists, which is unnecessary after "used by."
**Choice B is incorrect.** "cosmetic chemist''s" is the singular possessive, which is both wrong in number and incorrect as the object of "used by."
**Choice D is incorrect.** "cosmetic’s chemists" is ungrammatical: a noun followed by another noun with an apostrophe does not form a correct modifier here.
**Faster approach:** After "used by," expect a noun phrase (who does the using). Eliminate any choices showing possession (apostrophes) and pick the plain plural noun.'),
  ('79e232c1-26f9-5cbd-a231-085e64bb4c5d', 2, null, '**Choice C is correct.** The sentence links two independent ideas about popularity and eventual replacement, so it needs a coordinating conjunction. "century, but" correctly joins the clauses: "...the first half of the twentieth century, but these ingenious devices were eventually replaced by electronic calculators." The comma plus the conjunction "but" prevents a comma splice and clearly expresses the contrast.
**Choice A is incorrect.** "century," would create a comma splice because it would join two independent clauses with only a comma and no conjunction.
**Choice B is incorrect.** "century" with no punctuation or conjunction would produce a run-on or a sentence fragment connection that fails to signal the contrast between the clauses.
**Choice D is incorrect.** "century that" would create an ungrammatical or awkward subordinate clause ("century that these...") and does not convey the intended contrast.
**Faster approach:** Recognize two independent clauses expressing contrast; eliminate options that would create a comma splice or subordinate an independent clause. Always choose a coordinating conjunction with a comma (", but") for this pattern.'),
  ('7ea729ab-c249-56ee-9865-16feb370a139', 3, null, '**Choice D is correct.** The sentence reads smoothly with no additional punctuation after the name: “Her portrait of novelist Zadie Smith is displayed in the National Portrait Gallery in London.” Standard English requires no extra mark between a proper name and the following verb when the name is part of the subject.
**Choice A is incorrect.** An em dash would introduce an abrupt break or a parenthetical thought; nothing following the name requires that interruption here.
**Choice B is incorrect.** A colon would signal a list or explanation that follows the name, which does not occur.
**Choice C is incorrect.** A comma would create an unnecessary pause and could imply a nonrestrictive clause; the name is integral to the subject and needs no comma.
**Faster approach:** Read the sentence aloud; if the name directly connects to the verb with no parenthetical or list, choose no punctuation (plain name).'),
  ('4512ea9b-2174-52d1-af9d-60e62ba79b8f', 2, null, '**Choice C is correct.** The phrase names a specific person (drummer Dennis Chambers) who is being identified as the subject best known for work with Sugar Hill Records, so no commas are needed between the noun and the name: "American drummer Dennis Chambers may be best known..." This is a restrictive appositive that is essential to identify which American is meant.
**Choice A is incorrect.** A comma before the name ("drummer, Dennis Chambers") would incorrectly set off the name as a nonrestrictive appositive, implying the name is extra information rather than essential identification.
**Choice B is incorrect.** A comma after the name ("drummer Dennis Chambers,") leaves an unmatched comma before the main clause and disrupts sentence flow; it incorrectly suggests a pause where none is required.
**Choice D is incorrect.** Commas both before and after the name ("drummer, Dennis Chambers,") make the name a nonrestrictive appositive and also produce an unnecessary comma before the following clause, which is not appropriate here.
**Faster approach:** For noun + name phrases, decide whether the name is essential for identification. If it is essential (restrictive), use no commas; if it’s nonessential (extra detail), use commas to set it off. This rule applies to all appositives.'),
  ('4f2067d6-e2b7-56bf-b7f9-be7dc3be0ada', 1, null, '**Choice B is correct.** The word "however" is being used as a parenthetical interrupter in the middle of a single sentence that continues with the subordinating conjunction "since." The correct punctuation for a parenthetical like this is a comma before and after: "reach Earth’s surface, however, since..." This preserves the single-sentence structure and clearly signals the contrast without breaking the sentence.
**Choice A is incorrect.** It ends the parenthetical with a semicolon, creating a mismatched pair of comma/semicolon marks; the sentence still continues, so a semicolon is inappropriate.
**Choice C is incorrect.** A semicolon before "however" would separate two independent clauses, but the following clause begins with "since" and is not an independent clause.
**Choice D is incorrect.** A period before "However" would split the thought into two sentences; the second sentence would awkwardly begin with "However, since...", creating an unnatural sentence boundary.
**Faster approach:** Recognize "however" as a parenthetical interrupting a single sentence; punctuate it with commas on both sides when the sentence continues.'),
  ('a32e66b0-9da6-534a-98c5-93dfb45393a1', 0, null, '**Choice A is correct.** The sentence before the blank contrasts typical nocturnal migration with poisonous amphibians that migrate during the day; the clause after the blank—"with the sun in the sky, the amphibians'' striking color patterns deter visually oriented daytime predators..."—gives a statement about what happens during that daytime period. "At that time," properly signals the temporal link between the preceding clause ("during the day") and the ensuing explanation of why daytime migration is safe for these amphibians, so it creates a logical and cohesive transition.
**Choice B is incorrect.** "For example," introduces an example illustrating a general claim; here the sentence is not providing an example of a preceding generalization but is instead continuing the idea about what happens during the daytime, so "For example" is not appropriate.
**Choice C is incorrect.** "In other words," signals a restatement or clarification of a previous idea in different words. The following clause does not restate the prior clause but describes a related temporal consequence, so "In other words" misrepresents the relationship.
**Choice D is incorrect.** "However," signals contrast or exception. The second clause does not present a contrast with the first; it explains why daytime migration is safe, so a contrastive transition is wrong.
**Faster approach:** When a sentence after the blank refers to time (words like "with the sun," "during," "while"), choose a temporal transition such as "At that time." Scanning for temporal words lets you eliminate contrast or example markers quickly.'),
  ('866f3c2d-52e0-544a-931d-f4569b988e74', 0, null, '**Choice A is correct.** The sentence before the blank states that residents rely on the Cairo Metro for millions of trips each year, giving a reason why city officials would act; "For this reason," appropriately signals that the following clause explains a consequence or response to that fact: city officials strive to maintain the system’s 71 stations to keep journeys smooth.
**Choice B is incorrect.** "However," indicates a contrast, but the second clause does not contrast with residents relying on the metro; it explains the response to that reliance.
**Choice C is incorrect.** "For example," would introduce an illustration, but the second clause is not an example of the first statement—it is a direct consequence.
**Choice D is incorrect.** "Alternatively," offers a different option, which doesn’t fit because the sentence shows cause and effect, not alternatives.
**Faster approach:** Identify whether the sentence pair shows cause/effect, contrast, example, or alternative; then pick the transition that matches that relationship (here: cause → effect, so choose "For this reason").'),
  ('9c7b689e-b8ee-5ff5-9e51-7d0ef8e38927', 0, null, '**Choice A is correct.** The sentence states that box-modeled elements "lack organic realism," and the clause after the semicolon describes what must be done as a result: "post-modeling processes such as UV surface mapping are needed." That expresses a cause-and-effect relation, so a transition meaning "therefore/as a result" is required; "consequently" fits this relationship precisely.
**Choice B is incorrect.** "Similarly" indicates a comparison or likeness between two things, but the second clause does not compare two items — it states a consequence of the lack of realism, so a comparative transition is inappropriate.
**Choice C is incorrect.** "In sum" signals a brief summary of preceding points; the sentence instead introduces a resulting action, not a summary, so this transition does not match the logical connection.
**Choice D is incorrect.** "However" signals contrast or exception, but the second clause does not contradict the first; it follows from it. Because the intended relation is cause-and-effect rather than contrast, "however" is wrong.
**Faster approach:** Identify the logical relation between clauses (cause-effect, contrast, similarity, or summary) and pick the transition that matches that relation; here the second clause states a result, so choose a result transition like "consequently."'),
  ('58a32418-1dd0-5252-88a7-b611d867c8a8', 2, null, '**Choice C is correct.** The notes give the years each woman served: Betsy Morrow Humphrey, 1862–1880, and Thelma Austin, 1925–1941. Those date ranges place Betsy in the 19th century and Thelma in the 20th century, so saying Betsy worked in an earlier century than Thelma accurately emphasizes a clear difference between them.
**Choice A is incorrect.** Although true that a lighthouse keeper helps watercraft navigate, this choice emphasizes similarity rather than the requested difference and refers only to Thelma.
**Choice B is incorrect.** This rephrases Betsy’s role but focuses on a single person and repeats information rather than highlighting a contrast between the two keepers.
**Choice D is incorrect.** This states a similarity (both ensured safe navigation) and does not emphasize any difference between them, so it fails the prompt.
**Faster approach:** Compare the specific facts given (here, service years) to see which choice points out a contrast; for date-based differences, convert years to centuries to pick the choice that explicitly contrasts them.'),
  ('8ed636be-492c-520d-ae65-f0d218389ca4', 2, null, '**Choice C is correct.** It states the proposed sequence: about 160 million years ago Chrysalis came close to Saturn, tidal forces broke the moon apart, and the resulting debris formed Saturn’s rings — directly reflecting the notes'' timeline and causal chain.
**Choice A is incorrect.** It reverses the cause and effect by saying debris from Saturn’s rings caused Chrysalis to break apart, which contradicts the notes that say Chrysalis’s breakup produced the rings.
**Choice B is incorrect.** Although true that researchers proposed a moon that broke apart, it omits the timing, the tidal mechanism, and the claim that the debris formed the rings, so it fails to recount the full sequence.
**Choice D is incorrect.** This statement gives a general conditional about tidal forces but does not recount the specific sequence of events involving Chrysalis, the timing, or the formation of Saturn’s rings.
**Faster approach:** Look for the choice that presents events in chronological cause-and-effect order (time → mechanism → outcome); eliminate options that reverse causality or omit steps.'),
  ('1b49b2da-5f60-5ecb-9f4a-5639b47f2888', 0, null, '**Choice A is correct.** The notes state that the brown violetear has a “short, black, straight bill” and the little hermit has a “long, black, curved bill,” so emphasizing that both have black bills accurately synthesizes a clear similarity between the two species.
**Choice B is incorrect.** This sentence only restates details about the little hermit and does not draw a comparison or emphasize a similarity between the two birds.
**Choice C is incorrect.** Although it mentions a difference (size), it does not emphasize a similarity; the opening phrase “Though they share several traits in common” is unsupported by the rest of the sentence, which highlights the contrast instead.
**Choice D is incorrect.** This choice describes the book and its authors, not a similarity between the brown violetear and the little hermit.
**Faster approach:** Scan the notes for identical descriptors (words repeated for both birds); the shared descriptor is the quickest way to state a similarity—in this case, the word “black” describing both bills.'),
  ('d5c084b6-57ce-5873-8935-ad420b69674a', 3, null, '**Choice D is correct.** It explicitly links later media depiction to Wong Fei-hung’s transformation from a locally known figure into an internationally known folk hero, matching the student’s goal to emphasize the effect media had on building his legacy and using the notes about local recognition and widespread media portrayals.
**Choice A is incorrect.** It reverses causality: it claims media caused Wong’s local reputation as a physician and master, but the notes say he was already locally known for those roles and later became a media figure.
**Choice B is incorrect.** It notes that his abilities are depicted in many media and mentions the 1991 film, but it doesn’t emphasize that media built his international legacy.
**Choice C is incorrect.** It states that media depicted him and that he became an internationally known folk hero, but it presents those facts more neutrally; it lacks the clear causal emphasis that media "turned him into" an international folk hero that the student wants.
**Faster approach:** Eliminate choices that reverse cause and effect or only restate facts; pick the option that explicitly links media depiction to the change from local recognition to international fame.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Dec 2024 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('87ea1096-604d-53d8-b1ba-af331b936bda', 'PeaklyTest Dec 2024 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the Dec 2024 PeaklyTest · 27 questions · 32 minutes', 32, 181, true, 'PeaklyTest Dec 2024 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('c37fe2f9-e622-54cd-8257-aa6a93628f14', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice completes the text with the most logical and precise word or phrase?', '["breadth of", "controversy over", "confusion about", "apathy toward"]'::jsonb, 1, 'Possessing an outstanding collection of public art, Chicago has everything from monumental mosaics like Marc Chagall’s Four Seasons at sites like Chase Tower to innovative street art like Kashink’s mural Be The Change You Wish To See located on South Wabash Avenue. The _____ public art on display in the city can thus satisfy any art lover.'),
  ('ff4b1d92-1fbf-5a43-b482-d601cce408fd', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice completes the text with the most logical and precise word or phrase?', '["ambivalence", "acclaim", "foresight", "impartiality"]'::jsonb, 2, 'In a 2018 article about films depicting the experiences of Black Americans, critics for the New York Times praise Madeline Anderson’s 1970 film I Am Somebody as "galvanizing" and Carl Franklin’s 1995 film Devil in a Blue Dress as "picture perfect." Fans of the two films hope that such _____ will attract new audiences to these works.'),
  ('87a4215e-c004-58e4-a6da-f9903851d848', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice completes the text with the most logical and precise word or phrase?', '["exploit", "yield", "prioritize", "discern"]'::jsonb, 3, 'The fossil remains of the individual known as Misliya-1, discovered in Israel in 2002, can help paleoanthropologists not only _____ steps in the evolution of hominids but also illuminate the Pleistocene epoch generally, revealing important details about the time in which Misliya-1 lived.'),
  ('c8230a66-f2c2-5b8b-b4d1-2a0ba170085c', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which finding from the model tests, if true, would support the researchers'' hypothesis?', '["During the simulation, the structure with steel lower floors bent in high wind to a greater degree than did the structure with concrete lower floors.", "At the end of the simulation, the structure with concrete lower floors was several inches shorter than the structure with steel lower floors.", "During the simulation, when sudden forces caused vibrations in the structures, those vibrations took longer to disappear in the structure with steel lower floors than in the structure with concrete lower floors.", "At the end of the simulation, the structure with steel lower floors had slightly larger dimensions at its base than it did at the beginning of the simulation."]'::jsonb, 4, 'Throughout history, tall structures such as Gonbad-e Qabus in Iran or Hwangnyongsa in South Korea have posed a challenge to their architects, since these structures are more susceptible to physical forces than smaller structures. For example, the lower floors of a building must be able to support the enormous weight of the upper floors. To test a hypothesis that steel is more suitable than concrete for construction of a tall building’s lower floors, researchers created a computer model of two buildings that were identical except that one had concrete lower floors while one had steel lower floors, and simulated the effects of the forces of wind and gravity on those structures over the course of a century.'),
  ('3106735d-55b7-55dd-add6-7f9752d0022b', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice best describes the function of the underlined portion in the text as a whole?', '["It presents a reason most critics think the Aubrey/Maturin series should have the literary renown of similar works like The Forsyte Saga.", "It summarizes a positive assessment of a particular characteristic of the Aubrey/Maturin novels.", "It explains why many critics find the Aubrey/Maturin novels to be entertaining despite flaws in the novels'' structures.", "It argues that the unusual structure that O''Brian uses for HMS Surprise makes it one of his most entertaining books."]'::jsonb, 5, 'HMS Surprise, first published in 1973, is a novel in Patrick O''Brian’s Aubrey/Maturin series, which includes twenty completed books. Some critics have found fault with the abrupt endings of HMS Surprise and other books in the series, saying that they do not finish conclusively but arbitrarily stop. <u>But other critics</u> <u>argue that the books should not be thought of as discrete texts with traditional beginnings and endings</u> <u>but as a single incredibly long work, similar to other multivolume stories, such as John Galsworthy’s The</u> <u>Forsyte Saga.</u>'),
  ('0451da3f-1c80-50e1-ab1d-84f81b830fa1', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice best states the function of the underlined sentence in the text as a whole?', '["It indicates a distinction between the mechanics of two kinds of biological processes.", "It contrasts the frequency with which a biological phenomenon has been detected in two categories of organisms.", "It explains why a common perception of a biological process is flawed.", "It argues that two biological phenomena are more similar than they may initially appear to be."]'::jsonb, 6, 'Vertical gene transfer involves the transmission of genetic material from a parent to offspring; horizontal gene transfer, on the other hand, involves the exchange of genetic material between organisms not in a parent-offspring relationship. <u>While horizontal gene transfer is common among prokaryotes—single-</u><u>celled organisms, such as the bacteria Brevibacillus borstelensis and Lactococcus lactis—it has rarely</u> <u>been observed among eukaryotes (multicellular organisms).</u> However, new studies suggest that horizontal gene transfer is more common in eukaryotes than originally thought.'),
  ('e2f37112-db8c-5d35-ba40-5e2913e236ca', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Based on the texts, the author of Text 1 and the author of Text 2 would most likely agree with which statement?', '["The barriers used in Meding and Zasoski’s study effectively excluded root-to-root transmission of nutrients.", "A barrier that is impervious to both roots and fungal strands is necessary to evaluate nutrient transfer via a CMN.", "Excluding root-to-root transfer of nutrients between plants is sufficient to ensure that any observed nutrient transfer must involve a CMN.", "He and colleagues'' study did not find convincing evidence of nutrient transfer between individual plants."]'::jsonb, 7, '**Text 1**

In separate studies, Stephen Meding and Robert J. Zasoski and Xinhua He and colleagues examined whether plants transfer nutrients to one another using a common mycorrhizal network (CMN)—a lattice of fungal strands in the soil. Meding and Zasoski excluded all pathways other than the CMN by using barriers to keep the plants'' root systems separate while allowing mycorrhizal strands through—a crucial step He and colleagues'' study did not take.

**Text 2**

Meding and Zasoski took the necessary precaution of separating the plants'' root systems (thereby excluding root-to-root transmission). However, any barrier used must allow the thread-like hyphae of a CMN to pass through, and this permeability would also allow liquids through. Thus, the researchers'' experimental design cannot ensure that any nutrient transfer observed can be attributed to a CMN and not to some other pathway.'),
  ('233f9eee-01f7-5f99-94ed-d29332df8220', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice best describes the finding made by Curtis and colleagues, as presented in the text?', '["Increased lunar intensity is more beneficial for mongoose lemurs than it is for Arizona pocket mice.", "As lunar intensity increases, mongoose lemurs increase their foraging activity.", "During periods of high lunar intensity, mongoose lemurs increase their reliance on vision.", "As lunar intensity increases, Arizona pocket mice reduce their foraging activity."]'::jsonb, 8, 'Optimal foraging theory (OFT) holds that animals'' foraging behaviors reflect cost-benefit trade-offs that vary by species and with dynamic ecological circumstances. One such circumstance is lunar intensity, which Joel Brown and colleagues found to be negatively associated with foraging by Arizona pocket mice but Deborah J. Curtis and colleagues found to be positively associated with foraging by mongoose lemurs. This discrepancy is explicable in terms of OFT: the lemurs'' greater reliance on vision means that higher lunar intensity benefits them more than it benefits the mice.'),
  ('073f03d9-0aa2-5706-98fc-81be32e6ef18', '87ea1096-604d-53d8-b1ba-af331b936bda', 'According to the text, which factors seemed to be linked to the behavior of butterflies in Grace Herzel and colleagues'' study?', '["Weather conditions but not butterfly color", "Butterfly color but not weather conditions", "Neither butterfly color nor weather conditions", "Both butterfly color and weather conditions"]'::jsonb, 9, 'Biologist Grace Herzel and colleagues conducted a study of how butterfly color and weather conditions relate to butterfly behavior, which wouldn’t have been possible without data gathered by students and other amateur science enthusiasts in the community. Considering over three years'' worth of data, the researchers found that white butterflies were observed on green flowers more often than any other butterflies were, and that butterflies were observed to feed more often on cloudy days than on other days.'),
  ('4645fe48-d98b-528a-ae6c-72fa4ce4a5fd', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which finding, if true, would most directly support Martinez and colleagues'' conclusion?', '["Other bird species than M. barbatus also showed a tendency to freeze in place or scatter into vegetation when Martinez and colleagues played T. caesius alarm calls.", "Martinez and colleagues played alarm calls from different T. caesius individuals and observed no significant variation in the responses of M. barbatus.", "In some instances, M. barbatus froze in place or scattered into vegetation when Martinez and colleagues approached but before they began playing sounds.", "When Martinez and colleagues played control sounds of random noise in the vicinity of M. barbatus , the birds displayed no reaction."]'::jsonb, 10, 'The bird species Myiobius barbatus (the bearded flycatcher) shares some territory in French Guiana with Thamnomanes caesius (the cinereous antshrike), which emits a loud alarm call when it detects predators. Biologist Ari Martinez and colleagues recorded T. caesius alarm calls and played them in the vicinity of wild M. barbatus. Finding that the birds often froze in place or scattered into vegetation upon hearing the calls, they concluded that M. barbatus associates T. caesius alarm calls with danger.'),
  ('cfb798a9-6b4f-5e00-bf9c-96976118d00c', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice most effectively uses data from the table to complete the example?', '["P. Ian Ross and Martin G. Jalkotzy reported a maximum density of 4.70 individuals per 100 square kilometers, while the study by Richard Beausoleil et al., which used biopsy darting, reported a lower maximum density.", "Sean M. Murphy et al. reported a maximum density of only 1.65 individuals per 100 square kilometers, lower than that reported by several other studies.", "Richard A. Beausoleil et al. required a study area of 7,939 square kilometers, while the study by Sean M. Murphy et al. required a study area of 4,329 square kilometers.", "Lindsey N. Rich et al. reported a maximum density of 6.50 individuals per 100 square kilometers, higher than that reported by several other studies."]'::jsonb, 11, '**Studies of Cougar Population Density**

| Study authors | Location | Methods | Study area (square kilometers) | Maximum density (cougars per 100 square kilometers) |
| Lindsey N. Rich et al. | Belize, Bolivia, Argentina | regular camera trapping | 4,329 | 6.50 |
| Sean M. Murphy et al. | New Mexico (United States) | clustered camera trapping, GPS tracking of collars | 15,314 | 1.65 |
| P. Ian Ross and Martin G. Jalkotzy | Alberta (Canada) | radio-collar tracking | 780 | 4.70 |
| Richard A. Beausoleil et al. | Washington (United States) | biopsy darting | 7,939 | 2.40 |

Studies of the population density of cougars (Puma concolor) have yielded a range of results, which may in part reflect differences in the effectiveness of the methods that researchers have used in their studies. If, for example, the use of clustered camera trapping and GPS tracking of collars tends to lead to underestimates of cougar population density, that may explain why the study by ________'),
  ('98982622-0704-55e9-9f85-fae2bd4ca407', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which finding, if true, would most directly support Shcherbakova and colleagues'' claim?', '["Shcherbakova and colleagues'' analysis showed a slightly positive correlation between grammatical complexity and fusion.", "Shcherbakova and colleagues'' analysis showed a slightly negative correlation between grammatical complexity and exotericity.", "Shcherbakova and colleagues'' analysis showed a slightly positive correlation between fusion and exotericity and between informativity and exotericity.", "Shcherbakova and colleagues'' analysis showed a slightly negative correlation between grammatical complexity and fusion and between grammatical complexity and informativity."]'::jsonb, 12, 'The linguistic niche hypothesis (LNH) posits that the exotericity of languages (how prevalent non-native speakers are) and grammatical complexity are inversely related, which the LNH ascribes to attrition of complex grammatical rules as more non-native speakers adopt the language but fail to acquire those rules. Focusing on two characteristics that are positive indices of grammatical complexity, fusion (when new phonemes arise from the merger of previously distinct ones) and informativity (languages'' capacity for meaningful variation), Olena Shcherbakova and colleagues conducted a quantitative analysis for more than 1,300 languages and claim the outcome is inconsistent with the LNH.'),
  ('b312160f-fb40-5f37-9222-a9ea2ed8e03c', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice most effectively uses data from the graph to complete the statement?', '["P7’s ratings for impressionist and color-field paintings would differ from one another.", "P7 would derive more aesthetic pleasure from impressionist paintings than from color-field paintings.", "P7’s ratings for impressionist and color-field paintings would equal one another.", "P7 would derive less aesthetic pleasure from impressionist paintings than from color-field paintings."]'::jsonb, 13, '![figure](/q/dec24/001.webp)

Neuroscientist Kiyohito Iigaya and colleagues developed a computational model to predict how much a person will enjoy a particular work of art on a scale from 1 (not at all) to 4 (very much). They then recruited participants to use the same scale to rate several sets of paintings in various styles and calculated the correlation between the ratings predicted by the model and those reported by the participants. Assuming participant P7 gave equal ratings to the impressionist and color-field paintings, the data in the graph suggest that the model predicted that _____'),
  ('2a182cc7-e190-5911-8dec-64c0f18812e6', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice most logically completes the text?', '["Geoffrey of Monmouth’s accounts of Arthurian legends in History are more similar overall in content to the accounts in Culhwch and Olwen than they are to the accounts in Le Morte d''Arthur.", "when a version of an Arthurian legend contradicted the version in History, Malory preferred to include Geoffrey of Monmouth’s version in Le Morte d''Arthur.", "Le Morte d''Arthur is more historically accurate than History because Culhwch and Olwen had not been written when Geoffrey of Monmouth was writing his work.", "Malory encountered the Round Table in a source that Geoffrey of Monmouth was not familiar with when writing his History."]'::jsonb, 14, 'Arthurian legends (tales related to the character of King Arthur) derive from many often contradictory sources, such as Vita Sancti Cadoci, composed in the 11th century, and Culhwch and Olwen from the second half of the 12th century. Sir Thomas Malory’s 15th-century text Le Morte d''Arthur was an attempt to compile these stories into a coherent narrative. Many of Malory’s sources derive from Geoffrey of Monmouth’s History of the Kings of Britain, written in the 1130s. While neither History nor any works that predate it mention Arthur’s famous Round Table at which his knights assembled, Le Morte d''Arthur does, suggesting that _____'),
  ('96f7553e-cfe1-569c-982e-aa38e0ef81a8', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice most logically completes the text?', '["the differences that studies attribute to exposure to anthropogenic noise are likely to be more pronounced for amphibians than they are for mammals.", "some studies of amphibians found larger effects of exposure to anthropogenic noise than some studies of mammals did.", "the difference found in the study conducted by Graeme Shannon and colleagues was likely larger than the average difference for studies of black-tailed prairie dogs included in the meta-analysis.", "the studies in the meta-analysis that examined mammals were more likely than those that examined amphibians to specify whether the observed effects were detrimental."]'::jsonb, 15, 'Prolonged exposure to anthropogenic noise (sounds from human sources like traffic or mining) can affect animals, as Graeme Shannon and colleagues found in a 2016 study of black-tailed prairie dogs. Researchers conducted a meta-analysis of studies of how such noise affects animals and found that, for every study, relevant traits or behaviors of the animals were observably different between the exposed group and the otherwise similar but unexposed group. Although, on average, studies of mammals showed larger differences than studies of amphibians did, for every class of animals examined, there were individual studies showing differences well above the average for mammals. Therefore, the results of the meta analysis suggest that ____'),
  ('18e152f5-2220-542b-ba16-e1f691668fe9', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["rare,", "rare", "rare;", "rare and"]'::jsonb, 16, 'The term "retroflex" derives from Latin and means "bent back," an apt descriptor for the branch of consonantsretroflex consonantspronounced with the tongue curling up and back in the mouth. In many languages, including English, these consonants are _____ in some dialects of Mandarin, however, four such consonants ("ch," "sh," "zh," and "r") are relatively common.'),
  ('ade8f0ed-63d0-5c14-a7ed-b1647c4308b7', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["photosynthesis", "photosynthesis:", "photosynthesis and", "photosynthesis,"]'::jsonb, 17, 'Along with carbon dioxide concentration and temperature, light intensity affects the chemical reaction rate of _____ as light intensity increases, so does the rate at which the reactants (water and carbon dioxide) are converted into their products (glucose and oxygen).'),
  ('de9c5c8a-f603-5394-9faf-1305e59429ea', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["forming", "to form", "having formed", "form"]'::jsonb, 18, 'The fungus Tricholoma matsutake, commonly referred to as matsutake, is known to establish ectomycorrhizal bonds with certain pine tree species; in many cases, such symbiotic relationships, wherein fungal hyphae make contact with the pine’s root system, _____ extensive networks, which can be used to transport nutrients between trees.'),
  ('03ce2179-eb36-5873-b36c-49c791ebb9a8', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["drummer, Dennis Chambers,", "drummer Dennis Chambers", "drummer, Dennis Chambers", "drummer Dennis Chambers,"]'::jsonb, 19, 'Though he would go on to work with many respected bands, including CAB on their album CAB 2, American _____ may be best known for his time with Sugar Hill Records, where he helped craft the sound of early hip-hop music.'),
  ('d954bbe0-f821-5bf5-80c6-9b6b6030c19e', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Legler, however,", "Legler; however,", "Legler. However,", "Legler, however;"]'::jsonb, 20, 'Gretchen Legler’s short essay on "sound," a word referring to a large inlet or channel of a sea or ocean, is included in the collection Home Ground: A Guide to the American Landscape. The book wasn’t written solely by _____ other authors, such as Stephen Graham Jones and Barry Lopez, also contributed essays.'),
  ('2b0cb281-f30e-57f5-abde-3b8b2a96e486', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["nation Latvia.", "nation: Latvia.", "nation, Latvia.", "nation—Latvia."]'::jsonb, 21, 'The Organisation for Economic Co-operation and Development (OECD) tracks comparative price list data for its thirty eight member countries. According to this data, in July 2021, a "basket" of goods and services priced at 100 US dollars (USD) in the United States would have cost 66 USD in fellow OECD member _____'),
  ('20b53fb2-8459-5288-99d0-22e7d5e47ac7', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice completes the text with the most logical transition?', '["For example,", "In other words,", "Moreover,", "That said,"]'::jsonb, 22, 'In his painting At the Cycle Race Track, Jean Metzinger aims to depict a bike race in four-dimensional space. Of course, Metzinger’s painting doesn’t technically represent a fourth dimension; humans can only see in three dimensions. _____ by depicting the race through multiple, simultaneous perspectives, Metzinger offers a fascinating glimpse at what this other universe might look like.'),
  ('74a68672-b116-5004-b615-bb73662c8491', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice completes the text with the most logical transition?', '["Next,", "That being said,", "Hence,", "However,"]'::jsonb, 23, 'In 2015, geologist Peter Rogerson recalculated the geographic center of Nebraska, which had previously been determined in 1920 by the US Geological Survey (USGS). The USGS, Rogerson contended, had omitted important considerations, not least the curvature of the earth. _____ the state’s USGS-determined center—a point 10 miles northwest of the municipality of Broken Bow—was inaccurate.'),
  ('244d230f-44bc-5e08-b76c-5b5679273bde', '87ea1096-604d-53d8-b1ba-af331b936bda', 'Which choice completes the text with the most logical transition?', '["In addition,", "Therefore,", "Indeed,", "Nevertheless,"]'::jsonb, 24, 'On August 5, 1938, aviator Douglas Corrigan received a ticker-tape parade in New York City in recognition of his transatlantic flight. Of the 206 ticker-tape parades held between 1886 and 2022, a number were for achievements in aviation. ______ Corrigan’s parade was just one of 16 honoring pilots.'),
  ('3388d7aa-3c9f-5386-baaa-64801a1b8b52', '87ea1096-604d-53d8-b1ba-af331b936bda', 'The student wants to emphasize the order in which the two students attended the Bauhaus. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Founded in 1919, the Bauhaus was a German art and design school whose past students include Josef Albers and Stella Steyn.", "The Bauhaus was founded in 1919, and Stella Steyn began attending in 1931.", "Josef Albers and Stella Steyn were both Bauhaus students, but Albers, who began attending in 1920, preceded Steyn.", "Walter Gropius founded the Bauhaus in 1919 and acted as its director until 1928, at which point Hannes Meyer succeeded him in the role."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

The Bauhaus was an influential German art and design school founded in 1919 by Walter Gropius. Gropius was the school’s director from 1919 to 1928.
Hannes Meyer was its director from 1928 to 1930.
Ludwig Mies van der Rohe was its director from 1930 to 1933.
Josef Albers was a painter and educator who began attending the Bauhaus in 1920.
Stella Steyn was a painter and illustrator who began attending the Bauhaus in 1931.'),
  ('107ab3b8-01e4-5015-9057-7d5e95452c77', '87ea1096-604d-53d8-b1ba-af331b936bda', 'The student wants to contrast the two samples. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["In 2019, researchers studied the effect of torsional heating on various fibers, including samples of EPDM rubber and single-ply NiTi wire.", "The EPDM rubber sample used in the 2019 study was thicker than the single ply NiTi wire sample.", "Twisting an object will generally cause its temperature to increase, a process known as torsional heating.", "When the fibers were twisted as part of the 2019 study, the surface temperature of both samples increased."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Generally, an object will heat up when twisted.
The twisting of an object is known as torsion.
A 2019 study led by Zunfeng Liu and Ray Baughman tested the torsional heating of various fibers. When a 0.7-millimeter thick sample of single-ply nickel-titanium (NiTi) wire was twisted, its average surface temperature increased by 21.3°C.
When a 2-millimeter-thick sample of ethylene propylene diene monomer (EPDM) rubber fiber was twisted, its average surface temperature increased by 12°C.'),
  ('7293aa65-329f-5403-904d-8274e76fe712', '87ea1096-604d-53d8-b1ba-af331b936bda', 'The student wants to specify the total mass of Earth’s magnesium relative to that of all elements. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Magnesium’s abundance on Earth is greater than zinc''s, as reflected by magnesium’s higher mass fraction.", "Magnesium’s abundance can be expressed by a mass fraction, a measure of the element’s mass relative to that of all elements on Earth.", "The mass fraction of magnesium on Earth is 154,000 ppm.", "Magnesium’s mass relative to the combined mass of all elements on Earth is 40 ppm."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Element abundance is a relative measure of the amount of a chemical element in a given environment.
Abundance can be expressed as a mass fraction.
A mass fraction is the ratio of the total mass of an element to the combined mass of all elements in a given environment.
The mass fraction of magnesium (Mg) on Earth is 154,000 parts per million (ppm).
The mass fraction of zinc (Zn) on Earth is 40 ppm.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('c37fe2f9-e622-54cd-8257-aa6a93628f14', 0, null, '**Choice A is correct.** The sentence lists a wide range of public art—from monumental mosaics to innovative street art—so the noun that best fits is one indicating range or extent. "Breadth of" precisely conveys the variety of public art on display and naturally completes the sentence: "The breadth of public art on display in the city can thus satisfy any art lover."
**Choice B is incorrect.** "Controversy over" would imply disputes about the art; nothing in the passage suggests controversy, and that phrase conflicts with the positive, comprehensive description.
**Choice C is incorrect.** "Confusion about" implies people are uncertain about the art, which is not supported by the passage’s list of notable works and its claim that the collection can satisfy art lovers.
**Choice D is incorrect.** "Apathy toward" means indifference, which contradicts the statement that the city’s collection can "satisfy any art lover" and is therefore not appropriate.
**Faster approach:** Look for a word that matches the passage’s overall meaning (here, variety/range). When a sentence lists diverse examples, choose a word like "breadth" or "variety."'),
  ('ff4b1d92-1fbf-5a43-b482-d601cce408fd', 1, null, '**Choice B is correct.** The sentence says critics praise the films using positive terms like "galvanizing" and "picture perfect," and fans hope that this will attract new audiences. The noun that accurately names that positive response is "acclaim," which means praise or enthusiastic approval, so "such acclaim" fits both logically and grammatically.
**Choice A is incorrect.** "Ambivalence" means mixed or uncertain feelings; it contradicts the clearly positive critical language and would not lead to attracting new audiences.
**Choice C is incorrect.** "Foresight" refers to anticipating the future and does not describe critics'' praise or the kind of reaction that would draw audiences.
**Choice D is incorrect.** "Impartiality" means neutrality or lack of bias; critics being impartial is unrelated to the enthusiastic, positive wording and would not match the context that suggests praise.
**Faster approach:** Look for a word that mirrors the positive praise already quoted; choose the synonym ("acclaim") rather than words that imply neutrality, mixed feelings, or prediction.'),
  ('87a4215e-c004-58e4-a6da-f9903851d848', 3, null, '**Choice D is correct.** The sentence contrasts two things Misliya-1 helps paleoanthropologists do: one more specific action concerning "steps in the evolution of hominids" and another broader action, "illuminate the Pleistocene epoch." The verb needs to mean "perceive or identify" those evolutionary steps and to be parallel in sense to "illuminate." "Discern" precisely means to detect or recognize, so "discern steps" fits both grammatically and semantically.
**Choice A is incorrect.** "Exploit" means to take advantage of; it does not sensibly pair with "steps in the evolution" and would create an illogical meaning.
**Choice B is incorrect.** "Yield" is typically used with results (e.g., "yield information"), not with "steps," so it is not a precise fit here.
**Choice C is incorrect.** "Prioritize" means to rank by importance, which does not match the intended sense of recognizing or identifying evolutionary steps.
**Faster approach:** Look for a verb that logically pairs with "steps in the evolution" (recognize/identify) and that contrasts naturally with "illuminate"—this quickly narrows choices to "discern."'),
  ('c8230a66-f2c2-5b8b-b4d1-2a0ba170085c', 1, null, '**Choice B is correct.** The researchers hypothesized that steel is more suitable than concrete for a tall building’s lower floors, so a finding that the concrete-based building became several inches shorter than the steel-based building indicates greater compression or permanent deformation of the concrete under load; that outcome shows the steel lower floors performed better, supporting the hypothesis.
**Choice A is incorrect.** If the steel lower floors bent more in high wind, that would indicate worse performance for steel, which contradicts the hypothesis rather than supporting it.
**Choice C is incorrect.** Longer-lasting vibrations in the steel structure would indicate poorer damping or greater susceptibility to dynamic forces, again contradicting the idea that steel is more suitable.
**Choice D is incorrect.** An increase in base dimensions for the steel building suggests deformation or spreading at the base, which would be evidence of damage or instability rather than superior suitability.
**Faster approach:** Ask which result indicates better performance of steel than concrete; eliminate any choice that describes steel doing worse (more bending, longer vibrations, base deformation), leaving the choice that shows concrete performing worse.'),
  ('3106735d-55b7-55dd-add6-7f9752d0022b', 1, null, '**Choice B is correct.** The underlined sentence presents an alternative, favorable interpretation: some critics view the novels not as incomplete, separate books but as one continuous multivolume work. That wording functions as a concise positive assessment of a specific characteristic (their unity as a long, connected work) rather than developing plot or claiming entertainment value.
**Choice A is incorrect.** The sentence makes a comparison to multivolume works but does not claim these critics think the series deserves particular literary renown, nor does it say "most critics."
**Choice C is incorrect.** The sentence does not address entertainment or explain why readers find the books enjoyable; it discusses how to conceptualize their structure.
**Choice D is incorrect.** The sentence does not argue that the structure makes the book especially entertaining—only that the series can be seen as a single long work like The Forsyte Saga.
**Faster approach:** Look for signal words (here, "But other critics") and identify whether the sentence offers a positive evaluation of a trait, a counterargument, or a causal/explanatory claim; match that function to the choices.'),
  ('0451da3f-1c80-50e1-ab1d-84f81b830fa1', 1, null, '**Choice B is correct.** The underlined sentence uses the contrastive marker "While" and the adjectives "common" and "rarely" to compare how often horizontal gene transfer has been observed in prokaryotes versus eukaryotes. Its primary function is to state a difference in frequency between the two organism categories, which directly matches choice B.
**Choice A is incorrect.** The sentence does not describe how the processes work (mechanics); it only compares how frequently the phenomenon is observed in two groups.
**Choice C is incorrect.** The sentence does not explain why a perception is flawed; it merely reports observed frequency differences. The passage later notes new studies, but that is separate from the underlined sentence.
**Choice D is incorrect.** The sentence emphasizes a contrast in frequency, not a similarity between the two phenomena.
**Faster approach:** Look for contrast words (e.g., "while," "however") and frequency indicators (e.g., "common," "rarely") — they signal that the sentence is comparing how often something occurs across categories.'),
  ('e2f37112-db8c-5d35-ba40-5e2913e236ca', 0, null, '**Choice A is correct.** Both texts state that Meding and Zasoski used barriers to keep plants'' root systems separate, which excludes root-to-root transmission. Text 1 explicitly credits that exclusion as a “crucial step,” and Text 2 acknowledges that the researchers “took the necessary precaution of separating the plants'' root systems (thereby excluding root-to-root transmission).” Thus both authors agree that root-to-root transmission was effectively excluded.
**Choice B is incorrect.** Neither text claims a barrier impervious to both roots and fungal strands is necessary; in fact, such a barrier would block fungal hyphae and prevent testing CMN transfer.
**Choice C is incorrect.** Text 2 directly contradicts this by arguing that excluding root-to-root transfer is not sufficient because barriers that allow hyphae may also allow liquids.
**Choice D is incorrect.** Text 1 only notes that He and colleagues did not take the root-separation step; it does not report the outcomes of their study.
**Faster approach:** Scan both texts for explicit statements about the same experimental detail (here, root separation) and choose the option that echoes the shared explicit claim.'),
  ('233f9eee-01f7-5f99-94ed-d29332df8220', 1, null, '**Choice B is correct.** The passage states that Deborah J. Curtis and colleagues "found to be positively associated with foraging by mongoose lemurs," which means that as lunar intensity increases, the lemurs increase their foraging activity.
**Choice A is incorrect.** The passage does say lunar intensity benefits lemurs more than mice, but that is an explanation for the discrepancy rather than the specific finding reported by Curtis et al.; the direct finding is about increased foraging with increased lunar intensity.
**Choice C is incorrect.** The passage explains that lemurs rely more on vision, which makes higher lunar intensity beneficial, but it does not report that lemurs change their reliance on vision during brighter nights.
**Choice D is incorrect.** That statement describes Joel Brown and colleagues'' finding about Arizona pocket mice, not the finding made by Curtis and colleagues about mongoose lemurs.
**Faster approach:** Pick the choice that restates the passage’s explicit result word-for-word—look for the phrase "positively associated" (increase with increase) to identify the correct answer quickly.'),
  ('073f03d9-0aa2-5706-98fc-81be32e6ef18', 3, null, '**Choice D is correct.** The passage states that researchers found white butterflies were observed on green flowers more often than other butterflies and that butterflies fed more often on cloudy days. Those two findings show that both butterfly color and weather conditions were linked to butterfly behavior in the study.
**Choice A is incorrect.** The passage does report a weather-related finding (feeding more often on cloudy days) but it also reports a color-related finding, so saying color was not linked is wrong.
**Choice B is incorrect.** The passage does report that white butterflies favored green flowers, but it also explicitly links feeding behavior to weather, so weather conditions were indeed relevant.
**Choice C is incorrect.** The passage gives two specific links—one involving color and one involving weather—so it is not true that neither factor was linked to behavior.
**Faster approach:** Quickly scan the sentence reporting results for explicit links (e.g., “white butterflies…more often” and “fed more often on cloudy days”) and choose the answer that includes both mentioned factors.'),
  ('4645fe48-d98b-528a-ae6c-72fa4ce4a5fd', 3, null, '**Choice D is correct.** The researchers conclude that M. barbatus associates T. caesius alarm calls with danger; demonstrating that the birds do not react to control sounds of random noise shows that the response is specific to the alarm calls rather than to any sound or to the researchers'' presence. That specificity directly supports the association between the alarm calls and perceived danger.
**Choice A is incorrect.** That other species also respond shows the alarm call communicates danger broadly, but it does not directly demonstrate that M. barbatus specifically associates the call with danger.
**Choice B is incorrect.** Consistent responses to different individual callers supports reliability of the stimulus but does not rule out other explanations (for example, responses to any loud or similar call), so it is less direct than a control showing specificity.
**Choice C is incorrect.** If M. barbatus sometimes froze before sounds were played, that result would undermine rather than support the conclusion, suggesting their reactions might be caused by the researchers'' approach or other cues.
**Faster approach:** Look for a control that rules out alternative explanations (here, a nonalarm sound) —evidence that the response is specific to the alarm call is the quickest, most direct support for an association.'),
  ('cfb798a9-6b4f-5e00-bf9c-96976118d00c', 1, null, '**Choice B is correct.** The sentence hypothesizes that clustered camera trapping and GPS collar tracking lead to underestimates of cougar density; the table shows that Sean M. Murphy et al. used exactly those methods and reported a maximum density of only 1.65 cougars per 100 km², lower than the values reported in several other studies, so invoking Murphy et al. supports the hypothesis.
**Choice A is incorrect.** That choice compares Ross (4.70) and Beausoleil (2.40) but neither used clustered camera trapping with GPS collars, so it does not support the specific methodological explanation.
**Choice C is incorrect.** The study-area numbers are misstated (Murphy’s is 15,314 km², not 4,329 km²), and the comparison of area sizes is irrelevant to the given methodological claim.
**Choice D is incorrect.** While Rich reported 6.50 (the highest), the sentence needs a study that used clustered camera trapping and GPS tracking and reported a low value; Rich did not use those methods.
**Faster approach:** Scan the “Methods” column for the described method, then check that study’s density in the table; selecting the matching row is fastest.'),
  ('98982622-0704-55e9-9f85-fae2bd4ca407', 2, null, '**Choice C is correct.** The linguistic niche hypothesis predicts an inverse relationship between exotericity and grammatical complexity, so evidence that the two indices of grammatical complexity (fusion and informativity) are positively correlated with exotericity directly contradicts that prediction. If fusion and informativity increase as exotericity increases, the observed pattern is inconsistent with the LNH.
**Choice A is incorrect.** A positive correlation between grammatical complexity and fusion only links two measures of complexity; it does not address how complexity relates to exotericity, so it does not directly contradict the LNH.
**Choice B is incorrect.** A negative correlation between grammatical complexity and exotericity is exactly the relationship the LNH predicts, so this finding would support, not contradict, the LNH.
**Choice D is incorrect.** Negative correlations between grammatical complexity and its supposed indices (fusion and informativity) would call into question the measures of complexity but would not directly show that complexity and exotericity have the opposite relationship from the LNH prediction.
**Faster approach:** Translate the hypothesis into a predicted sign (negative) for the correlation between exotericity and complexity, then pick the answer that gives the opposite (positive) relationship between exotericity and the complexity measures.'),
  ('b312160f-fb40-5f37-9222-a9ea2ed8e03c', 0, null, '**Choice A is correct.** The graph shows that the model’s predicted correlations for P7 are different for the two styles: the light-gray bar (P7) is near 0.28 for Impressionist and near 0.25 for Color field, so the model predicts unequal ratings for those styles even though the prompt says P7 actually gave equal ratings.
**Choice B is incorrect.** That choice claims the model predicted P7 would prefer Impressionist to Color field; the graph does show a slightly higher correlation for P7 with Impressionist, but correlation indicates how well the model’s predictions match P7’s ratings, not that the model predicted higher pleasure for one style over the other — and the question asks whether the model predicted equal ratings.
**Choice C is incorrect.** If the model had predicted equal ratings, P7’s correlation values for the two styles would be the same; the light-gray bars for Impressionist and Color field are different heights, so the model did not predict equal ratings.
**Choice D is incorrect.** That choice asserts the model predicted less pleasure from Impressionist than Color field for P7, but the light-gray bar for Impressionist is actually slightly higher than the one for Color field, so the model did not predict that ordering.
**Faster approach:** To answer any Command of Evidence question about model predictions vs. reported ratings, directly compare the heights of the bars for the same subject across categories; equal heights would indicate equal predicted ratings, different heights indicate the model predicted different ratings.'),
  ('2a182cc7-e190-5911-8dec-64c0f18812e6', 3, null, '**Choice D is correct.** The passage notes that Geoffrey’s History and earlier works do not mention the Round Table, but Malory’s Le Morte d''Arthur does. That contrast implies that Malory must have gotten the Round Table detail from a different source that postdates or was unknown to Geoffrey; in other words, Malory encountered that detail in a source Geoffrey was not familiar with when he wrote his History.
**Choice A is incorrect.** The passage gives no basis for comparing overall similarity of Geoffrey’s account to Culhwch and Olwen versus Le Morte d''Arthur; it only discusses the presence or absence of the Round Table.
**Choice B is incorrect.** The passage simply notes Malory included the Round Table; it does not say Malory systematically preferred Geoffrey’s versions in cases of contradiction.
**Choice C is incorrect.** Nothing in the passage supports a claim about relative historical accuracy, and the timing of Culhwch and Olwen does not establish that point.
**Faster approach:** Use timeline elimination — if an element appears in a later work but not in earlier sources, infer the later author obtained it from a source not used by the earlier author; eliminate choices that assert unsupported comparisons or preferences.'),
  ('96f7553e-cfe1-569c-982e-aa38e0ef81a8', 1, null, '**Choice B is correct.** The passage says that although mammals showed larger average differences than amphibians, "for every class of animals examined, there were individual studies showing differences well above the average for mammals." That explicitly means that some amphibian studies reported effects larger than some mammal studies, which is exactly what choice B states.
**Choice A is incorrect.** It contradicts the passage, which states that mammals, on average, showed larger differences than amphibians, so it cannot claim amphibian differences are likely more pronounced than mammal differences.
**Choice C is incorrect.** The passage compares classes of animals and individual studies across classes; it gives no basis for comparing the single Shannon prairie-dog study to the average of prairie-dog studies in the meta-analysis.
**Choice D is incorrect.** The passage discusses magnitudes of observed differences, not whether studies specified that effects were detrimental, so there is no support for this claim.
**Faster approach:** Focus on the exact comparative language in the sentence about averages and "individual studies showing differences well above the average for mammals"; translate that directly into which choices claim that some amphibian studies exceeded some mammal studies and eliminate contradicting options.'),
  ('18e152f5-2220-542b-ba16-e1f691668fe9', 2, null, '**Choice C is correct.** The sentence joins two independent clauses and requires stronger separation than a comma; a semicolon before the transitional adverbial phrase "in some dialects of Mandarin, however, ..." correctly links the clauses without creating a comma splice. The resulting sentence — "these consonants are rare; in some dialects of Mandarin, however, four such consonants ... are relatively common" — is grammatically correct and clear.
**Choice A is incorrect.** Inserting a comma creates a comma splice by joining two independent clauses with only a comma, which is nonstandard.
**Choice B is incorrect.** Leaving no punctuation produces a run-on sentence and fails to separate the independent clauses properly.
**Choice D is incorrect.** Adding "and" creates an awkward and ungrammatical construction that does not logically connect the clauses.
**Faster approach:** For sentences that join two independent clauses with a transition (e.g., however), use a semicolon before the transition (or make two sentences); avoid simple commas to prevent comma splices.'),
  ('ade8f0ed-63d0-5c14-a7ed-b1647c4308b7', 1, null, '**Choice B is correct.** The sentence sets up a clause that restates or explains the preceding idea, so a colon properly introduces that explanation: "Along with carbon dioxide concentration and temperature, light intensity affects the chemical reaction rate of photosynthesis: as light intensity increases, so does the rate..." The colon signals that what follows is a direct elaboration of how light intensity affects
photosynthesis, which matches the sentence structure.
**Choice A is incorrect.** A simple period or no punctuation between "photosynthesis" and the following clause would create a run-on sentence; it would not provide the grammatical signal that the second clause explains the first.
**Choice C is incorrect.** "photosynthesis and" would require an additional element coordinated with "photosynthesis" (e.g., "photosynthesis and respiration") but none is provided, leaving the sentence grammatically incomplete.
**Choice D is incorrect.** A comma after "photosynthesis" would create a comma splice by improperly joining two independent clauses without an appropriate conjunction; a colon is the correct punctuation to introduce the explanatory clause.
**Faster approach:** When a clause that follows explains, illustrates, or restates the preceding clause, immediately choose a colon. This single rule reliably distinguishes colons from commas or conjunctions in explanatory constructions.'),
  ('de9c5c8a-f603-5394-9faf-1305e59429ea', 3, null, '**Choice D is correct.** The sentence contains a nonrestrictive parenthetical clause beginning with "wherein" ("wherein fungal hyphae make contact with the pine’s root system"). The main clause resumes after that comma, so the plural subject "symbiotic relationships" requires a finite verb: "form extensive networks." "Form" correctly completes the main clause and agrees in number with "relationships."
**Choice A is incorrect.** "Forming" would create a participial phrase modifying "relationships," which could be grammatical, but here the punctuation and clause structure call for a finite verb resuming the main clause rather than a participle.
**Choice B is incorrect.** "To form" would create an infinitival phrase and would not properly continue the main clause after the parenthetical "wherein" clause.
**Choice C is incorrect.** "Having formed" is a perfect participle that creates a misplaced time relationship and does not grammatically resume the main clause.
**Faster approach:** Identify the parenthetical "wherein" clause; then supply a finite verb that agrees with the main subject that appears before it (here, the plural "relationships"), so use "form."'),
  ('03ce2179-eb36-5873-b36c-49c791ebb9a8', 1, null, '**Choice B is correct.** The phrase "drummer Dennis Chambers" is an essential (restrictive) appositive that identifies which American is meant, so it should not be set off by commas. The sentence reads correctly as "American drummer Dennis Chambers may be best known..." without additional punctuation.
**Choice A is incorrect.** The commas around the name create a nonrestrictive appositive, which would imply the name is extra information; the sentence intends the name to identify which American, so commas are wrong. Also the trailing comma after "Chambers," is erroneous before "may."
**Choice C is incorrect.** A single comma before the name but not after it produces a punctuation imbalance and disrupts the sentence; nonrestrictive appositives require commas both before and after the name.
**Choice D is incorrect.** The comma after "Chambers" is unnecessary and incorrect because the appositive is essential and should not be set off by commas.
**Faster approach:** Ask whether the name is essential to identify the person; if yes, choose the version without commas (restrictive appositive).'),
  ('d954bbe0-f821-5bf5-80c6-9b6b6030c19e', 3, null, '**Choice D is correct.** The sentence contains two independent clauses: "Gretchen Legler’s short essay ... is included in the collection Home Ground: A Guide to the American Landscape" and "other authors, such as Stephen Graham Jones and Barry Lopez, also contributed essays." To link these with the transitional adverb "however" while preserving correct punctuation, use a comma after the first clause and a semicolon after the transitional word when the second clause itself contains commas. The correct punctuation is "Legler, however;" which places a comma before the interrupter and a semicolon after it to set off the entire interrupter phrase and separate the independent clauses cleanly.
**Choice A is incorrect.** "Legler, however," uses a comma both before and after "however," but that leaves only a comma between two independent clauses, creating a comma splice.
**Choice B is incorrect.** "Legler; however," places a semicolon before "however" and a comma after, which is not the conventional way to set off a mid-sentence interrupter and then join independent clauses; the more standard pattern here is comma before the interrupter and semicolon after it when the following clause contains internal commas.
**Choice C is incorrect.** "Legler. However," makes "However" the start of a new sentence, which is grammatically acceptable by itself but changes the intended flow; additionally, when the second clause contains internal commas ("other authors, such as..."), using a semicolon before the interrupter in the original sentence better preserves clarity and mirrors the punctuation expected in a single complex sentence.
**Faster approach:** For sentences that insert a transitional word like "however" between two independent clauses, put a comma before the transitional phrase and a semicolon after it when the remainder of the sentence contains internal commas; this avoids comma splices and keeps the sentence clear.'),
  ('2b0cb281-f30e-57f5-abde-3b8b2a96e486', 0, null, '**Choice A is correct.** The name of the country is an essential identifier (a restrictive appositive) that specifies which of the OECD’s many member countries is meant, so it should follow the general noun without being set off by punctuation. "fellow OECD member nation Latvia" correctly places the proper name immediately after the noun it identifies.
**Choice B is incorrect.** A colon is not used to join a noun to an immediate appositive in running text; it would create an awkward, incorrect break ("nation: Latvia").
**Choice C is incorrect.** A comma would make "Latvia" nonessential (parenthetical), but the country name is essential to identify which member is meant.
**Choice D is incorrect.** An em dash unnecessarily sets off the name as an abrupt aside; that punctuation is inappropriate for this essential identifier.
**Faster approach:** If a proper name identifies which member of a class is meant, treat it as essential and eliminate answers that insert commas, dashes, or colons before the name.'),
  ('20b53fb2-8459-5288-99d0-22e7d5e47ac7', 3, null, '**Choice D is correct.** The sentence before the blank presents a concession (the painting doesn’t literally show a fourth dimension), and the clause after the blank explains what Metzinger nonetheless accomplishes. "That said," signals a contrast or qualification that connects the concession to the subsequent positive claim, so "That said, by depicting the race through multiple, simultaneous perspectives, Metzinger offers a fascinating glimpse..." reads logically and smoothly.
**Choice A is incorrect.** "For example," introduces an illustration of a preceding claim, but the following clause explains a contrasting or qualifying point rather than giving an example of the earlier statement.
**Choice B is incorrect.** "In other words," indicates a restatement or clarification of the previous idea; here the next clause is not a restatement of "humans can only see in three dimensions" but a contrasting point about what the painting nonetheless achieves.
**Choice C is incorrect.** "Moreover," adds additional support or information, which doesn’t fit the needed contrast after a concession; the sentence requires a transition that signals qualification rather than mere addition.
**Faster approach:** When a sentence contains a concession or limiting clause (words like "of course", "however", or negative information), immediately pick a contrasting/qualifying transition (e.g., "that said," "however,") rather than additive or example transitions.'),
  ('74a68672-b116-5004-b615-bb73662c8491', 2, null, '**Choice C is correct.** The preceding sentence reports Rogerson’s contention that the USGS omitted important considerations (including Earth’s curvature); therefore a transitional word that indicates a logical consequence is required. "Hence," correctly signals that the omitted considerations lead to the conclusion that the USGS-determined center was inaccurate.
**Choice A is incorrect.** "Next," indicates sequence or order, which doesn’t fit here because the sentence presents a conclusion, not the next step in a sequence.
**Choice B is incorrect.** "That being said," introduces a contrast or qualification and would undermine rather than support the conclusion implied by Rogerson’s contention.
**Choice D is incorrect.** "However," also signals contrast and would suggest that the following clause opposes Rogerson’s claim, which is the opposite of the intended logical result.
**Faster approach:** Identify whether the prior sentence sets up a cause/result or a contrast; choose a transition that signals consequence (e.g., "thus/hence/therefore") for conclusions and a contrast word (e.g., "however") for contradictions.'),
  ('244d230f-44bc-5e08-b76c-5b5679273bde', 2, null, '**Choice C is correct.** The second sentence makes a general statement that some ticker-tape parades honored aviation achievements, and the final sentence provides a confirming example: Corrigan’s parade was one of 16 honoring pilots. "Indeed" is the transition that signals confirmation or reinforcement of the previous claim, so it logically connects the sentences.
**Choice A is incorrect.** "In addition" suggests adding new, separate information. The final sentence is not merely additional but confirms the general statement, so this is weaker than "Indeed."
**Choice B is incorrect.** "Therefore" indicates a logical consequence, but the final sentence is not a conclusion drawn from the general statement; it is an example that supports it.
**Choice D is incorrect.** "Nevertheless" signals contrast, which does not fit because the final sentence does not contradict the previous statement but rather reinforces it.
**Faster approach:** Choose a transition by identifying whether the next sentence is confirming, adding, concluding, or contrasting the previous one; then pick the word that matches that relationship (confirmation → "Indeed").'),
  ('3388d7aa-3c9f-5386-baaa-64801a1b8b52', 2, null, '**Choice C is correct.** It directly compares the two students and gives the relevant attendance dates from the notes: Josef Albers began attending in 1920 and Stella Steyn in 1931, so Albers preceded Steyn. The sentence both identifies them as Bauhaus students and uses the specific dates to make the order clear.
**Choice A is incorrect.** Though it names both students, it gives no dates or comparative language, so it does not emphasize the order in which they attended.
**Choice B is incorrect.** It mentions only Stella Steyn and the founding date; it fails to reference Josef Albers or directly compare their attendance, so it doesn’t emphasize the order.
**Choice D is incorrect.** It discusses the founders and directors, not the two students, and therefore does not address the order in which Albers and Steyn attended.
**Faster approach:** Look for the answer that explicitly names both students and includes their attendance dates or a direct comparative phrase (e.g., “preceded” or “followed”); that choice will show order immediately.'),
  ('107ab3b8-01e4-5015-9057-7d5e95452c77', 1, null, '**Choice B is correct.** It directly contrasts the two samples by noting a clear difference given in the notes: the EPDM rubber sample was 2 millimeters thick while the single-ply NiTi wire sample was 0.7 millimeters thick, so the EPDM sample was thicker than the NiTi sample.
**Choice A is incorrect.** It restates that both fibers were studied in 2019 but does not contrast any characteristic of the two samples.
**Choice C is incorrect.** It provides a general definition of torsional heating (a similarity or background statement) rather than contrasting the two specific samples.
**Choice D is incorrect.** It notes a similarity (both samples’ temperatures increased) but fails to contrast how the samples differ in thickness or in the amount their temperatures rose.
**Faster approach:** Look for the answer that states a specific difference between the two samples (numeric or descriptive) rather than a general fact or similarity.'),
  ('7293aa65-329f-5403-904d-8274e76fe712', 2, null, '**Choice C is correct.** The student asked for a specification of the total mass of Earth’s magnesium relative to all elements; stating the mass fraction does exactly that. The notes give the mass fraction of magnesium on Earth as 154,000 ppm, so Choice C directly provides the required measure.
**Choice A is incorrect.** It only makes a comparative claim (Mg > Zn) and does not give the actual mass fraction or quantify magnesium’s total mass relative to all elements.
**Choice B is incorrect.** It correctly explains what a mass fraction is but does not supply the numeric value needed to specify magnesium’s total mass relative to all elements.
**Choice D is incorrect.** It gives 40 ppm, which the notes identify as zinc’s mass fraction, so it misattributes zinc’s value to magnesium and thus gives an incorrect specification.
**Faster approach:** For synthesis questions asking for a specified quantity, choose the answer that provides the numeric value (the mass fraction in ppm) rather than a definition or a comparison.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

