insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('9e737137-91f1-5520-9b0c-483fd8a38879', '86d90024-10b7-52b5-b0e1-065291a36c12', 'The graph of a system of two linear equations is shown. The solution to the system is $(x,y)$. What is the value of $y$?', '["$-5$", "$-4$", "$2$", "$3$"]'::jsonb, 1, '![figure](/q/dec24/002.webp)'),
  ('b073ad9f-2c04-5d9c-8e5e-702366e1c342', '86d90024-10b7-52b5-b0e1-065291a36c12', 'The function $f$ is defined by $f(x) = 15x + 10$. What is the value of $f(x)$ when $x = 2$?', '["$27$", "$30$", "$40$", "$50$"]'::jsonb, 2, null),
  ('3ecc309c-eedb-502e-9cb2-80d0707be7d9', '86d90024-10b7-52b5-b0e1-065291a36c12', 'In the xy-plane, the graph of $y = f(x)$ is a line that passes through $(0,21)$ and has a slope of $4$. Which equation defines $f$?', '["$f(x) = 21x$", "$f(x) = 21x + 4$", "$f(x) = 4x$", "$f(x) = 4x + 21$"]'::jsonb, 3, null),
  ('da07d593-923b-5a75-b99a-4eb5f5c2789e', '86d90024-10b7-52b5-b0e1-065291a36c12', 'The table shows three values of $x$ and their corresponding values of $y$. There is a linear relationship between $x$ and $y$. Which of the following equations represents this relationship?', '["$y = x + 22$", "$y = 24x$", "$y = 24x + 2$", "$y = 22x$"]'::jsonb, 4, '| $x$ | $y$ |
| 0 | 22 |
| 1 | 23 |
| 2 | 24 |'),
  ('1e365db8-b8da-5a60-a941-fd4a658bd7e6', '86d90024-10b7-52b5-b0e1-065291a36c12', 'One of the two equations in a system of linear equations is given. The system has infinitely many solutions. If the second equation in the system is $y = mx + b$, where $m$ and $b$ are constants, what is the value of $b$?
$y = \frac{2}{5}x + 2$', '["$-2$", "$\\frac{1}{2}$", "$-\\frac{1}{2}$", "$2$"]'::jsonb, 5, null),
  ('c4fd44fd-cea5-5a6e-921d-dde066affd64', '86d90024-10b7-52b5-b0e1-065291a36c12', 'An object was launched upward from a platform. The graph shown models the height above ground, $y$ , in meters, of the object $x$ seconds after it was launched. For which of the following intervals of time was the height of the object increasing for the entire interval?', '["From $x = 0$ to $x = 2$", "From $x = 0$ to $x = 4$", "From $x = 2$ to $x = 3$", "From $x = 3$ to $x = 4$"]'::jsonb, 6, '![figure](/q/dec24/003.webp)'),
  ('b16d34c6-10dc-5390-83b2-fe490a67565d', '86d90024-10b7-52b5-b0e1-065291a36c12', 'The relationship between the variables $r$ and $y$ is defined by an exponential equation. When $x = 0$, the value of $y$ is $90$, and for every increase in the value of $x$ by $1$, the corresponding value of $y$ increases by $20%$ of its previous value. Which equation represents this relationship?', '["$y = 90(1.20)^{x}$", "$y = 90(1.02)^{x}$", "$y = 20(1.90)^{x}$", "$y = 20(1.09)^{x}$"]'::jsonb, 7, null),
  ('7e5d7a51-e19b-573c-93b8-7099c3a979da', '86d90024-10b7-52b5-b0e1-065291a36c12', 'The table shows the amount of time it took a participant in a study to complete each tasks. What was the mean time, in minutes, for this participant to complete a task?', '["$8$", "$10$", "$11$", "$12$"]'::jsonb, 8, '| Task | Time (minutes) |
| A | 8 |
| B | 6 |
| C | 14 |
| D | 11 |
| E | 11 |'),
  ('c084f504-f730-5e05-ab36-4ce33c6664f0', '86d90024-10b7-52b5-b0e1-065291a36c12', 'The function $h$ is defined by $h(x) = 7∣x∣$. What is the value of $h(-2)$?', '["$-14$", "$5$", "$9$", "$14$"]'::jsonb, 9, null),
  ('cbc945ed-8703-5e63-b488-9e606ee619ad', '86d90024-10b7-52b5-b0e1-065291a36c12', 'Which of the following is closest to the slope of the line of best fit shown?', '["$-11.19$", "$-0.84$", "$0.84$", "$11.19$"]'::jsonb, 10, '![figure](/q/dec24/004.webp)'),
  ('673aab4f-641e-5f96-9915-74a04d7f023f', '86d90024-10b7-52b5-b0e1-065291a36c12', 'In the figure, line $q$ is parallel to line $r$, and both lines are intersected by line $s$. If $y = 2x + 7$, what is the value of $x$?', '["$35$", "$42$", "$48$", "$58$"]'::jsonb, 11, '![figure](/q/dec24/005.webp)'),
  ('b32d7809-0a02-51c5-9c22-b317cc7af8e7', '86d90024-10b7-52b5-b0e1-065291a36c12', 'Raheem bought 9 shirts that were each the same price. He used a coupon for \$54 off the entire purchase. The cost for the entire purchase after using the coupon was \$108. What was the original price, in dollars, for 1 shirt?', '[]'::jsonb, 12, null),
  ('f613b527-f6e3-5861-b03e-5182b7537de0', '86d90024-10b7-52b5-b0e1-065291a36c12', 'Line $t$ in the xy-plane has a slope of $-\frac{1}{3}$ and passes through the point $(9,4)$. Which equation defines line $t$?', '["$y = 7x - \\frac{1}{3}$", "$y = 9x + 4$", "$y = -\\frac{x}{3} + 4$", "$y = -\\frac{x}{3} + 7$"]'::jsonb, 13, null),
  ('3fed2e87-fa26-5de1-8594-b435af81f8b8', '86d90024-10b7-52b5-b0e1-065291a36c12', '$(x - 16)(x - 12)(x + 7)(x + 13) = 0$ What is a positive solution to the given equation?', '[]'::jsonb, 14, null),
  ('e7ee1399-ad98-5a1d-ba9f-c80bf56e9108', '86d90024-10b7-52b5-b0e1-065291a36c12', 'A right circular cone has a height of $13$ centimeters (cm) and a base with a radius of $6$ cm. What is the volume, in cm³, of this cone?', '["$26π$", "$78π$", "$156π$", "$468π$"]'::jsonb, 15, null),
  ('01d22b98-4513-5153-96f9-de2d10d70a6a', '86d90024-10b7-52b5-b0e1-065291a36c12', 'A linear model estimates the population of a city from 1995 to 2019. The model estimates the population was $55$ thousand in 1995, $217$ thousand in 2015, and $x$ thousand in 2019. To the nearest whole number, what is the value of $x$?', '[]'::jsonb, 16, null),
  ('bdb6bb43-80ac-5f7c-a645-99ddfe4d039f', '86d90024-10b7-52b5-b0e1-065291a36c12', 'The equation gives the estimated number of online newsletter subscribers at the end of every six-month period, $x$, starting from the end of January 1997, where $0 < x < 4$. Which statement is the best interpretation of the $y$-intercept of the graph of this equation in the $xy$-plane?
$y = 500(2)^{2x}$', '["The estimated number of online newsletter subscribers at the end of the first six-month period was 500.", "The estimated number of online newsletter subscribers at the end of January 1997 was 500.", "The estimated number of online newsletter subscribers at the end of January 1998 was 1,000.", "The estimated number of online newsletter subscribers at the end of January 1997 was 1,000."]'::jsonb, 17, null),
  ('a5fa166f-2d7d-59c6-b2bb-db7061fc685e', '86d90024-10b7-52b5-b0e1-065291a36c12', '$\frac{x}{7} + 5(y - 14) = 29$
$\frac{x}{3} - 5(y - 14) = 41$
The solution to the given system of equations is $(x,y)$. What is the value of $10x$?', '[]'::jsonb, 18, null),
  ('d6e340d7-51df-5d2f-8926-9190589dd2b6', '86d90024-10b7-52b5-b0e1-065291a36c12', 'When several resistors are connected in series in a circuit, the total resistance of the circuit is the sum of the resistances of these resistors. A certain circuit consists of $8$ resistors connected in series, where the resistance of each resistor is positive. This circuit has a total resistance of $130$ ohms. The total resistance of $3$ resistors in this circuit is $90$ ohms. Which inequality best represents all possible values of the resistance $c$, in ohms, of one of the other $5$ resistors in this circuit?', '["$0 < x < 8$", "$0 < x < 40$", "$40 < x < 90$", "$40 < x < 130$"]'::jsonb, 19, null),
  ('5cf5919f-f1f3-5baa-b7d4-553fe0dec753', '86d90024-10b7-52b5-b0e1-065291a36c12', 'A family has money in an account for renting movies online. Each time the family rents a movie, the cost of the rental is withdrawn from the account, and each rental costs the same amount of money. The function $f(m) = 21 - 3m$ gives the amount of money, in dollars, in the account after the family has rented $m$ movies. Which of the following represents the amount of money, in dollars, withdrawn from the account each time the family rents a movie?', '["$3m$", "$3$", "$21$", "$21 - 3m$"]'::jsonb, 20, null),
  ('4d3bb110-8b5e-5c98-8f1f-902304a1d502', '86d90024-10b7-52b5-b0e1-065291a36c12', 'If $9 - 4(4 - 9x) = 2 - 5(4 - 9x)$, what is the value of $4 - 9x$?', '[]'::jsonb, 21, null),
  ('69447624-6dd9-58bd-afaf-bfaad889c1a7', '86d90024-10b7-52b5-b0e1-065291a36c12', 'On a plot of land, $52.0%$ of the square footage is farmland and the remaining square footage is pasture. There are buildings on exactly $21.5%$ of the square footage of the farmland, and there are buildings on exactly $14.0%$ of the square footage of the pasture. If there are buildings on exactly $p%$ of the square footage of the plot of land, what is the value of $p$?', '[]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('9e737137-91f1-5520-9b0c-483fd8a38879', 2, null, '**Choice C is correct.** The two lines intersect at the point (-2, 2). On the graph the intersection lies on the horizontal grid line two units above the x-axis, so the y-coordinate of the solution to the system is $2$.
**Choice A is incorrect.** $-5$ is well below the x-axis, but the intersection point is above the x-axis, so $y = -5$ does not match the graph.
**Choice B is incorrect.** $-4$ is also below the x-axis; the plotted intersection is positive, so $-4$ is not correct.
**Choice D is incorrect.** $3$ is one grid line higher than the intersection; the intersection lies on $y = 2$, not $y = 3$.
**Faster approach:** For any graphed system, find where the two lines cross and read the y-coordinate directly from the grid (count squares from the x-axis) rather than computing equations.'),
  ('b073ad9f-2c04-5d9c-8e5e-702366e1c342', 2, null, '**Choice C is correct.** The function is $f(x) = 15x + 10$. Substituting $x = 2$ gives $f(2) = 15(2) + 10 = 30 +$ $10 = 40$, so choice C, $40$, is the correct value.
**Choice A is incorrect.** $27$ would come from $15(1) + 12$ or another unrelated computation; it does not match $15(2) + 10$.
**Choice B is incorrect.** $30$ equals $15(2)$ but omits the $+10$ term in the function, so it is not $f(2)$.
**Choice D is incorrect.** $50$ would be $15(2) + 20$ or $15(frac83) + 10$, which does not correspond to $x = 2$ in the given rule.
**Faster approach:** Directly plug $x = 2$ into the expression and perform the arithmetic: multiply first ( $15imes2 = 30$), then add $10$ to get $40$. This substitution method works for any evaluation of a linear function.'),
  ('3ecc309c-eedb-502e-9cb2-80d0707be7d9', 3, null, '**Choice D is correct.** A line with slope $4$ and passing through $(0,21)$ has $y$-intercept $21$, so in slope-intercept form $y = mx + b$ we have $y = 4x + 21$, which defines $f(x)$ as $f(x) = 4x + 21$.
**Choice A is incorrect.** $f(x) = 21x$ has slope $21$ and intercept $0$, not slope $4$ and intercept $21$.
**Choice B is incorrect.** $f(x) = 21x + 4$ has slope $21$ and intercept $4$, so it does not match the given slope or intercept.
**Choice C is incorrect.** $f(x) = 4x$ has correct slope $4$ but intercept $0$, not the required intercept $21$.
**Faster approach:** Use slope-intercept form $y = mx + b$; plug in $m = 4$ and the point $(0,21)$ gives $b = 21$, so $y = 4x + 21$ immediately.'),
  ('da07d593-923b-5a75-b99a-4eb5f5c2789e', 0, null, '**Choice A is correct.** The table shows that when $x$ increases by 1, $y$ increases by 1, so the slope is $1$. Using the point $(0,22)$ (the $y$-intercept), the equation is $y = 1 \cdot x + 22$, i.e. $y = x + 22$.
**Choice B is incorrect.** $y = 24x$ has slope $24$ and gives $y = 0$ when $x = 0$, which does not match the table’s $y(0) = 22$.
**Choice C is incorrect.** $y = 24x + 2$ has slope $24$ (not $1$) and gives $y = 2$ at $x = 0$, not $22$.
**Choice D is incorrect.** $y = 22x$ has slope $22$ and gives $y = 0$ at $x = 0$, not $22$, so it does not fit the table.
**Faster approach:** Check successive differences to find slope (here +1 per +1 in $x$) and read the $y$ value at $x =$ $0$ for the intercept, then write $y = \text{slope} \cdot x + \text{intercept}$.'),
  ('1e365db8-b8da-5a60-a941-fd4a658bd7e6', 3, null, '**Choice D is correct.** For a system of two linear equations to have infinitely many solutions, the equations must represent the same line. The given line is $y = \frac{2}{5}x + 2$, so the second line $y = mx + b$ must have the same slope and the same intercept: $m = \frac{2}{5}$ and $b = 2$. Thus $b = 2$.
**Choice A is incorrect.** $b = -2$ would give a different y-intercept, so the two lines would be distinct and intersect at most once, not infinitely many times.
**Choice B is incorrect.** $b = \frac{1}{2}$ also changes the y-intercept, so the lines would not coincide and would not have infinitely many solutions.
**Choice C is incorrect.** $b = -\frac{1}{2}$ likewise produces a different line; therefore the system would not have infinitely many solutions.
**Faster approach:** For infinitely many solutions, the two equations must be identical, so directly match slope and intercept; read off $b = 2$.'),
  ('c4fd44fd-cea5-5a6e-921d-dde066affd64', 0, null, '**Choice A is correct.** The graph shows the height rising from the launch at $x = 0$ to the peak at $x = 2$, so the function $y(x)$ has positive slope on the entire interval $[0,2]$; therefore the height is increasing for the entire interval from $x = 0$ to $x = 2$.
**Choice B is incorrect.** Although the height increases from $x = 0$ to $x = 2$, it decreases after the peak at $x =$ $2$ and returns to ground by $x = 4$, so the height is not increasing on the entire interval $[0,4]$.
**Choice C is incorrect.** At $x = 2$ the graph is at its maximum and for $x > 2$ the curve falls, so the height is decreasing on $[2,3]$, not increasing.
**Choice D is incorrect.** The graph is descending between $x = 3$ and $x = 4$ (approaching ground), so the height is not increasing on $[3,4]$.
**Faster approach:** Identify whether the graph’s slope is positive or negative over each interval; the object increases only where the curve rises (here from 0 to the peak at 2 seconds), so select that interval immediately.'),
  ('b16d34c6-10dc-5390-83b2-fe490a67565d', 0, null, '**Choice A is correct.** The general form for exponential growth with initial value $y_{0}$ and growth rate $r$ per unit is $y = y_{0}(1 + r)^{x}$. Here $y(0) = 90$, so $y_{0} = 90$, and an increase of 20% per 1 unit means $r = 0.20$, so the factor is $1.20$. Thus $y = 90(1.20)^{x}$, choice A.
**Choice B is incorrect.** The base $1.02$ corresponds to a 2% growth per unit, not the required 20%.
**Choice C is incorrect.** This choice has the wrong initial value ($20$ instead of $90$) and a growth factor $1.90$ that would mean a 90% increase each step.
**Choice D is incorrect.** This also has the wrong initial value and the base $1.09$ corresponds to a 9% growth, not 20%.
**Faster approach:** Identify the initial value (the value at $x = 0$) and use $1+$growth rate as the base; here that gives $90(1 + 0.20)^{x}$ immediately.'),
  ('7e5d7a51-e19b-573c-93b8-7099c3a979da', 1, null, '**Choice B is correct.** The mean is the sum of the times divided by the number of tasks. The times are $8 + 6 +$ $14 + 11 + 11 = 50$, and there are 5 tasks, so the mean is $50 \div 5 = 10$ minutes.
**Choice A is incorrect.** A mean of 8 would require the total to be $8 \times 5 = 40$, but the actual total is 50.
**Choice C is incorrect.** A mean of 11 would require a total of $11 \times 5 = 55$, which is larger than the actual total of 50.
**Choice D is incorrect.** A mean of 12 would require a total of $12 \times 5 = 60$, also larger than the actual total.
**Faster approach:** For any mean problem, add all values to get the total and then divide by the count; pairing numbers to make round sums (e.g., $8 + 11 = 19$, $6 + 14 = 20$, plus 11 gives $19 + 20 + 11 = 50$) can speed mental addition.'),
  ('c084f504-f730-5e05-ab36-4ce33c6664f0', 3, null, '**Choice D is correct.** The function is $h(x) = 7∣x∣$. For $x = -2$, $∣x∣ = ∣ - 2∣ = 2$, so $h(-2) = 7 \cdot 2 = 14$, which matches choice D.
**Choice A is incorrect.** $-14$ would be $7 \cdot (-2)$, but the absolute value makes the input positive, so $-14$ is not correct.
**Choice B is incorrect.** $5$ does not result from $7 \cdot ∣-2∣$; there is no combination here that yields 5.
**Choice C is incorrect.** $9$ is not equal to $7 \cdot 2$, so it is not the value of $h(-2)$.
**Faster approach:** Compute the absolute value first, $∣ - 2∣ = 2$, then multiply by 7: $7 \times 2 = 14$. This two-step process (absolute value, then multiply) works for any function of the form $k∣x∣$.'),
  ('cbc945ed-8703-5e63-b488-9e606ee619ad', 1, null, '**Choice B is correct.** Reading two points on the fitted line (for example the line is about $y = 11$ at $x = 0$ and about $y = 4.3$ at $x = 8$), the slope is change in $y$ over change in $x$: $m \approx (4.3 - 11)/(8 - 0) = -6.7/8 \approx$ $-0.8375$, which is closest to $-0.84$.
**Choice A is incorrect.** A slope of $-11.19$ is far too steep; the plotted line falls only a few units over several units in $x$, not about eleven units per one unit in $x$.
**Choice C is incorrect.** The sign is wrong: the line clearly slopes downward from left to right, so the slope must be negative, not positive $0.84$.
**Choice D is incorrect.** A positive $11.19$ is both the wrong sign and an implausibly large magnitude compared to the gentle downward trend shown.
**Faster approach:** Pick two obvious grid intersections on the line, compute $Δy/Δx$ quickly (rise over run), and compare to choices; this avoids estimating many individual points.'),
  ('673aab4f-641e-5f96-9915-74a04d7f023f', 2, null, '**Choice C is correct.** Since lines $q$ and $r$ are parallel and line $s$ is a transversal, the angles marked as $77°$ and $y°$ are corresponding angles. Corresponding angles are equal when the lines are parallel, so we have:
$y = 77°.$
It is given that $y = 2x + 7$. Therefore, we can set up the equation:
$2x + 7 = 77.$
Next, solve for $x$:
Subtract 7 from both sides: $2x + 7 - 7 = 77 - 7$, which simplifies to $2x = 70$.
Divide both sides by 2: $x = \frac{70}{2}$, which simplifies to $x = 35$.
Therefore, the correct value of $x$ is **35**.
**Explanation of Incorrect Choices:**
**Choice A (** $35$**):** This is actually the correct answer; however, if an oversight led to considering it wrong, it could have been due to mistakenly solving the equation incorrectly.
**Choice B (** $42$**):** This could result from incorrectly setting the equation, perhaps by misplacing the values during subtraction or dividing by an incorrect number.
**Choice D (** $58$**):** This could be a miscalculation by setting up the equation wrongly or making an arithmetic error when solving for $x$.'),
  ('b32d7809-0a02-51c5-9c22-b317cc7af8e7', null, array['18']::text[], '**The correct answer is 18.** Let $p$ be the original price of one shirt. Raheem bought 9 shirts, so the total before the coupon was $9p$. After applying a \$54 coupon the final cost was $9p - 54$, and we are told this equals \$108. Solve $9p - 54 = 108$. Add 54 to both sides to get $9p = 162$, then divide by 9 to find $p = 18$. Thus each shirt originally cost \$18.
**Faster approach:** Translate the situation into an equation immediately: original total = final total + coupon, so $9p = 108 + 54 = 162$, then divide by 9 to get $p = 18$. This direct setup works for any similar problem.'),
  ('f613b527-f6e3-5861-b03e-5182b7537de0', 3, null, '**Choice D is correct.** Use point-slope form: $y - 4 = -\frac{1}{3}(x - 9)$. Simplifying gives $y = -\frac{1}{3}x + 3 + 4 = y =$ $-\frac{1}{3}x + 7$, which matches choice D.
**Choice A is incorrect.** Its slope is $7$, not $-\frac{1}{3}$, so it cannot be line $t$.
**Choice B is incorrect.** Its slope is $9$, not $-\frac{1}{3}$, and it does not pass through $(9,4)$ (plugging in gives $y = 9 \cdot 9 +$ $4 \ne 4$).
**Choice C is incorrect.** Although the slope $-\frac{1}{3}$ matches, the $y$-intercept is $4$, but substituting $x = 9$ into $y =$ $-\frac{1}{3}x + 4$ gives $y = 1$, not $4$, so it does not pass through $(9,4)$.
**Faster approach:** For slope $m$ and point $(x_{0},y_{0})$, compute $b = y_{0} - mx_{0}$ to get the $y$-intercept, then write $y = mx + b$ (or quickly test the given choices by plugging in $x = 9,y = 4$).'),
  ('3fed2e87-fa26-5de1-8594-b435af81f8b8', null, array['12']::text[], '**The correct answer is 12.** The equation is a product of four linear factors: $(x - 16)(x - 12)(x + 7)(x +$ $13) = 0$. For a product of factors to equal zero, at least one factor must be zero. Setting each factor equal to zero gives the solutions $x = 16$, $x = 12$, $x = -7$, and $x = -13$. The positive solutions are $16$ and $12$, so one positive solution is $12$.
**Faster approach:** Use the zero-product property immediately: set each factor equal to zero and read off the solutions. Pick any positive root produced (here $12$ or $16$).'),
  ('e7ee1399-ad98-5a1d-ba9f-c80bf56e9108', 2, null, '**Choice C is correct.** The volume V of a cone is $V = \frac{1}{3}π r^{2}h$. Here $r = 6$ and $h = 13$, so $V = \frac{1}{3}π(6^{2})(13) =$ $\frac{1}{3}π(36)(13) = 12 \cdot 13π = 156π \text{cm}^{3}$.
**Choice A is incorrect.** $26π$ is far too small; it would result from miscomputing $\frac{1}{3}π r^{2}h$ by using $r^{2} = 6^{2}$ but dividing by an extra factor (or using $r = 6$ without squaring).
**Choice B is incorrect.** $78π$ is half of the correct value; it would occur if one mistakenly used $\frac{1}{6}π r^{2}h$ or computed $\frac{1}{3}π r^{2}h$ but halved the product.
**Choice D is incorrect.** $468π$ is three times the correct value and would result from omitting the $\frac{1}{3}$ factor in the cone volume formula (using $πr^{2}h$ instead).
**Faster approach:** Compute $r^{2} = 36$, divide by 3 to get 12, then multiply by 13 to get $156$, so $156π$ — do these three quick mental steps for any cone volume problem.'),
  ('01d22b98-4513-5153-96f9-de2d10d70a6a', null, array['249']::text[], '**The correct answer is 249.** Let the linear model be $P(t)$ where $t$ is the year. From 1995 to 2015 (20 years) the population increases from 55 to 217 thousand, a change of $217 - 55 = 162$ thousand, so the yearly rate of change is $162/20 = 8.1$ thousand per year. From 2015 to 2019 is 4 years, so the increase is $4 \cdot 8.1 = 32.4$ thousand. Thus $x = 217 + 32.4 = 249.4$, which rounds to 249 thousand to the nearest whole number.
**Faster approach:** Compute the annual increase $(217 - 55)/20 = 8.1$ and apply it over the 24 years from 1995 to 2019: $55 + 24 \cdot 8.1 = 249.4$, round to 249. This method (find unit rate then scale) works for any linear trend problem.'),
  ('bdb6bb43-80ac-5f7c-a645-99ddfe4d039f', 1, null, '**Choice B is correct.** The y-intercept of the graph is the value of $y$ when $x = 0$. Substituting $x = 0$ into $y =$ $500(2)^{2x}$ gives $y = 500(2)^{0} = 500(1) = 500$, so the model estimates 500 subscribers at the starting time, which is the end of January 1997.
**Choice A is incorrect.** The end of the first six-month period corresponds to $x = 1$, and $y = 500(2)^{2} =$ $500(4) = 2000$, not 500.
**Choice C is incorrect.** The end of January 1998 is one year later (two six-month periods, $x = 2$), giving $y =$ $500(2)^{4} = 500(16) = 8000$, not 1000.
**Choice D is incorrect.** As shown above, at $x = 0$ the value is 500, so the estimate at the end of January 1997 is not 1000.
**Faster approach:** Recognize the y-intercept means $x = 0$, so directly compute $y(0) = 500$ to interpret the starting number of subscribers.'),
  ('a5fa166f-2d7d-59c6-b2bb-db7061fc685e', null, array['1470']::text[], '**The correct answer is 1470.** Let t = 5(y-14). Then the system becomes x/7 + t = 29 and x/3 - t = 41. Solve each for x: from the first, x = 7(29 - t) = 203 - 7t; from the second, x = 3(41 + t) = 123 + 3t. Set them equal: 203 - 7t = 123 + 3t, so 80 = 10t and t = 8. Substitute back to get x = 203 - 7(8) = 203 - 56 = 147. Therefore 10x = 10(147) = 1470.
**Faster approach:** Notice the terms $5(y - 14)$ are oppositely signed; add the two equations to eliminate that term immediately: $x/7 + x/3 = 70$, solve for $x$ by combining fractions to get $x = 147$, then compute $10x =$ $1470$.'),
  ('d6e340d7-51df-5d2f-8926-9190589dd2b6', 1, null, '**Choice B is correct.** The total of all 8 resistors is 130 ohms and 3 of them total 90 ohms, so the remaining 5 resistors together total $130 - 90 = 40$ ohms. Each of these 5 resistances is positive, so any one resistance $c$ must satisfy $0 < c < 40$ (it cannot equal 40 because the other four would then have to sum to 0, contradicting positivity).
**Choice A is incorrect.** The upper bound 8 is far too small; the five resistors sum to 40, so an individual resistor can be much larger than 8.
**Choice C is incorrect.** Values greater than 40 are impossible because the five resistors together only sum to 40, so no one of them can exceed 40.
**Choice D is incorrect.** The interval $40 < x < 130$ both excludes values less than 40 (which are allowed) and allows values greater than 40 (which are impossible).
**Faster approach:** Subtract the known subtotal (130−90=40) to get the sum of the 5 resistors, then use positivity: each must be >0 and less than 40 because the other four contribute a positive amount.'),
  ('5cf5919f-f1f3-5baa-b7d4-553fe0dec753', 1, null, '**Choice B is correct.** The function $f(m) = 21 - 3m$ is linear in $m$ with slope $-3$, so each additional movie reduces the balance by \$3. Equivalently, compute $f(m + 1) - f(m) = [21 - 3(m + 1)] - [21 - 3m] = -3$, so \$3 is withdrawn per rental.
**Choice A is incorrect.** $3m$ grows with $m$ and would represent a total withdrawn after $m$ rentals, not the constant amount withdrawn for each single rental.
**Choice C is incorrect.** $21$ is the starting balance $f(0)$, not the per-rental withdrawal.
**Choice D is incorrect.** $21 - 3m$ is the remaining balance after $m$ rentals (the given function), not the amount taken out each time.
**Faster approach:** For any linear model $f(m) = a + bm$, the per-unit change is the coefficient $b$ (here $-3$), so the absolute withdrawal per rental is \$3; or quickly compute $f(1)$ and $f(0)$ and take the difference.'),
  ('4d3bb110-8b5e-5c98-8f1f-902304a1d502', null, array['-7']::text[], '**The correct answer is -7.** Let $t = 4 - 9x$. Substituting $t$ into the given equation gives $9 - 4t = 2 - 5t$. Add $5t$ to both sides to get $9 + t = 2$. Subtract $9$ from both sides to find $t = 2 - 9 = -7$. Therefore $4 - 9x = -7$.
**Faster approach:** Whenever the same linear expression appears on both sides of an equation, replace it with a single variable (here $t$) and solve the resulting simple linear equation. This eliminates repeated algebraic manipulation and quickly yields the value of the repeated expression.'),
  ('69447624-6dd9-58bd-afaf-bfaad889c1a7', null, array['17.9']::text[], '**The correct answer is 17.9.** Let the total area be 100 square units so percentages convert directly to areas. Farmland is 52 units, and buildings occupy $21.5%$ of that, which is $0.215 \times 52 = 11.18$ units. Pasture is the remaining $48$ units, and buildings occupy $14.0%$ of that, which is $0.14 \times 48 = 6.72$ units. The total area with buildings is $11.18 + 6.72 = 17.90$ units, so $p = 17.9%$.
**Faster approach:** Work with total area 100 so you can multiply percentages directly: $p = 52(0.215) +$ $48(0.14) = 11.18 + 6.72 = 17.9$. This avoids converting back and forth between fractions and percents.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

